class _Proyecto:
    """Lightweight reference to a saved project — works with Supabase or local files."""
    def __init__(self, name: str, id: str = None, path: pathlib.Path = None):
        self.name   = name
        self._id    = id
        self._path  = path
        self._resumen = {}
        self._tipo    = ""
        self._zona    = ""
        self._fecha   = ""
        self._nombre  = name


@st.cache_resource
def _get_supabase():
    """Cliente Supabase compartido entre todas las sesiones — una conexión para todos los usuarios."""
    try:
        from supabase import create_client
        _sb = st.secrets.get("supabase", {}) or {}
        _url = _sb.get("url", "")
        _key = _sb.get("key", "")
        return create_client(_url, _key) if (_url and _key) else None
    except Exception as _e:
        _log.error("_get_supabase: no se pudo crear cliente Supabase: %s", _e)
        return None


def _sb_set_user_context(sb, username: str) -> None:
    """Establece el contexto de usuario para las políticas RLS de proyectos.

    Las políticas RLS de SOLUM usan current_setting('app.current_user') para
    asegurar que cada usuario solo vea sus propios proyectos. Esta función debe
    llamarse antes de cualquier operación en la tabla proyectos.

    Args:
        sb: Cliente Supabase activo.
        username: Nombre de usuario del sesión actual (st.session_state._username).
    """
    if not sb or not username:
        return
    try:
        sb.rpc("set_app_user", {"p_user": username}).execute()
    except Exception as _e:
        # No bloquear la operación si falla — loguear y continuar
        # (el código de la app ya filtra por usuario en las queries como defensa en profundidad)
        _log.warning("_sb_set_user_context: no se pudo establecer contexto RLS para '%s': %s", username, _e)


def _sb_set_share_token_context(sb, token: str) -> None:
    """Establece el share_token en contexto de sesión para la policy proyectos_share_token_read.

    Permite que la vista pública (sin login) lea un proyecto específico por su token.

    Args:
        sb: Cliente Supabase activo.
        token: Share token de 32 chars (uuid.uuid4().hex).
    """
    if not sb or not token:
        return
    try:
        sb.rpc("set_app_user", {"p_user": ""}).execute()   # sin usuario en vista pública
        # Seteamos el share_token en la config de sesión via SQL directo
        sb.postgrest.session.headers.update({"x-share-token": token})
    except Exception as _e:
        _log.warning("_sb_set_share_token_context: error seteando contexto de token: %s", _e)


def _sb_exec(fn, max_retries: int = 3, base_wait: float = 1.0):
    """Ejecuta una operación Supabase con reintentos y backoff exponencial.

    Args:
        fn: Callable sin argumentos que ejecuta la operación Supabase.
        max_retries: Número máximo de intentos (default 3).
        base_wait: Espera inicial en segundos; se duplica en cada reintento.

    Returns:
        El resultado de fn() si tiene éxito.

    Raises:
        Exception: Si todos los reintentos fallan, relanza la última excepción.
    """
    last_err = None
    for attempt in range(max_retries):
        try:
            return fn()
        except Exception as _e:
            last_err = _e
            if attempt < max_retries - 1:
                wait = base_wait * (2 ** attempt)   # 1s → 2s → 4s
                _log.warning("_sb_exec intento %d/%d falló (%s) — reintentando en %.1fs",
                             attempt + 1, max_retries, _e, wait)
                time.sleep(wait)
    _log.error("_sb_exec falló en todos los %d intentos: %s", max_retries, last_err)
    raise last_err


def guardar_proyecto(nombre: str, estado: dict, tipo: str = "", zona: str = "") -> "_Proyecto":
    if not tipo:
        if "industrial_result" in estado:
            tipo = "industrial"
        elif "residencial_result" in estado:
            tipo = "residencial"
        else:
            tipo = "inmobiliario"
    if not zona:
        zona = str(estado.get("zona") or "")
    usuario = st.session_state.get("_username", "unknown")
    sb = _get_supabase()
    if sb:
        _sb_set_user_context(sb, usuario)   # Establece contexto RLS antes de INSERT
        try:
            row = {
                "usuario": usuario,
                "nombre_proyecto": nombre.strip() or "sin_nombre",
                "tipo": tipo,
                "zona": zona,
                "datos": estado,
                "resumen": estado.get("resumen") or {},
            }
            resp = _sb_exec(lambda: sb.table("proyectos").insert(row).execute())
            if resp.data:
                _id = resp.data[0]["id"]
                display = f"{nombre.strip() or 'sin_nombre'}  ·  {datetime.datetime.now().strftime('%d/%m/%Y')}"
                return _Proyecto(display, id=_id)
        except Exception as _e:
            _log.warning("guardar_proyecto Supabase falló (3 intentos) — usando fallback local: %s", _e)
    PROJECTS_DIR.mkdir(exist_ok=True)
    slug = re.sub(r"[^\w\-]", "_", nombre.strip())[:40]
    fp = PROJECTS_DIR / f"{slug}_{datetime.datetime.now().strftime('%Y%m%d_%H%M')}.json"
    with open(fp, "w", encoding="utf-8") as f:
        json.dump({**estado, "nombre": nombre, "fecha": datetime.datetime.now().isoformat()}, f, ensure_ascii=False, indent=2)
    return _Proyecto(fp.name, path=fp)


def listar_proyectos(con_resumen: bool = False) -> list:
    usuario = st.session_state.get("_username", "unknown")
    sb = _get_supabase()
    if sb:
        _sb_set_user_context(sb, usuario)   # Establece contexto RLS antes de SELECT
        try:
            cols = "id, nombre_proyecto, tipo, zona, creado_en" + (", resumen" if con_resumen else "")
            resp = _sb_exec(lambda: (
                sb.table("proyectos")
                  .select(cols)
                  .eq("usuario", usuario)
                  .order("creado_en", desc=True)
                  .limit(100)
                  .execute()
            ))
            result = []
            for row in (resp.data or []):
                fecha = (row.get("creado_en") or "")[:10]
                tipo_tag = row.get("tipo") or ""
                display = f"{row['nombre_proyecto']}  [{tipo_tag}  ·  {fecha}]"
                p = _Proyecto(display, id=row["id"])
                if con_resumen:
                    p._resumen = row.get("resumen") or {}
                    p._tipo    = tipo_tag
                    p._zona    = row.get("zona") or ""
                    p._fecha   = fecha
                    p._nombre  = row.get("nombre_proyecto") or display
                result.append(p)
            return result
        except Exception as _e:
            _log.warning("listar_proyectos Supabase falló — usando fallback local: %s", _e)
    if not PROJECTS_DIR.exists():
        return []
    return [
        _Proyecto(fp.name, path=fp)
        for fp in sorted(PROJECTS_DIR.glob("*.json"), key=lambda x: x.stat().st_mtime, reverse=True)
    ]


def cargar_proyecto(ref) -> dict:
    if isinstance(ref, _Proyecto) and ref._id:
        sb = _get_supabase()
        if sb:
            _owner = st.session_state.get("_username", "")
            _sb_set_user_context(sb, _owner)   # Establece contexto RLS antes de SELECT
            try:
                resp = _sb_exec(lambda: (
                    sb.table("proyectos").select("datos")
                      .eq("id", ref._id).eq("usuario", _owner).single().execute()
                ))
                return (resp.data or {}).get("datos") or {}
            except Exception as _e:
                _log.warning("cargar_proyecto Supabase falló (3 intentos) — intentando fallback local: %s", _e)
    if isinstance(ref, _Proyecto):
        path = ref._path
    elif isinstance(ref, pathlib.Path):
        path = ref
    else:
        path = pathlib.Path(str(ref))
    if path and path.exists():
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    return {}


_SHARE_TOKEN_TTL_DAYS = 30   # Los tokens expiran a los 30 días

def generar_link_compartido(proyecto_id: str, ttl_days: int = _SHARE_TOKEN_TTL_DAYS) -> str:
    """Genera token único con TTL configurable, lo guarda en Supabase y retorna la URL completa.

    Args:
        proyecto_id: ID del proyecto en Supabase.
        ttl_days: Días de vigencia del link. 0 = sin vencimiento. Default: 30.
    """
    token = uuid.uuid4().hex          # 32 chars hex — 128 bits de entropía
    if ttl_days > 0:
        expira = (datetime.datetime.utcnow() + datetime.timedelta(days=ttl_days)).isoformat() + "Z"
    else:
        expira = None  # sin vencimiento
    sb = _get_supabase()
    if sb and proyecto_id:
        # Establece contexto RLS — UPDATE solo funciona si el usuario es dueño del proyecto
        _sb_set_user_context(sb, st.session_state.get("_username", ""))
        try:
            # Guarda token + fecha de expiración en columna top-level
            _sb_exec(lambda: sb.table("proyectos").update({
                "share_token": token,
                "share_token_expires_at": expira,
            }).eq("id", proyecto_id).execute())
        except Exception as _e:
            _log.warning("generar_link_compartido: fallo en update share_token — intentando fallback JSONB: %s", _e)
            try:
                # Fallback: guarda dentro del JSONB datos
                resp = _sb_exec(lambda: sb.table("proyectos").select("datos").eq("id", proyecto_id).single().execute())
                datos = dict((resp.data or {}).get("datos") or {})
                datos["_share_token"] = token
                datos["_share_token_expires_at"] = expira
                _sb_exec(lambda: sb.table("proyectos").update({"datos": datos}).eq("id", proyecto_id).execute())
            except Exception as _e2:
                _log.error("generar_link_compartido: fallo total al guardar token — proyecto_id=%s err=%s", proyecto_id, _e2)
                return ""
    base = (st.secrets.get("app") or {}).get("base_url", "http://localhost:8501")
    return f"{base}?share={token}"


def _irr_bisect(flujos, lo=-0.9999, hi=10.0, tol=1e-7, max_iter=300):
    """Bisection method to find monthly IRR."""
    def npv(r):
        return sum(f / (1 + r) ** i for i, f in enumerate(flujos))
    try:
        v_lo, v_hi = npv(lo), npv(hi)
        if v_lo * v_hi > 0:
            return None
        for _ in range(max_iter):
            mid = (lo + hi) / 2
            if abs(hi - lo) < tol:
                return mid
            if npv(mid) * v_lo < 0:
                hi = mid
            else:
                lo = mid
                v_lo = npv(lo)
        return (lo + hi) / 2
    except Exception as _e:
        _log.warning("_irr_bisect falló con flujos=%d items: %s", len(flujos), _e)
        return None


