def calcular_oficinas(r: dict) -> dict:
    """Motor financiero Oficinas — 3 modos: Alquiler / Compra / Desarrollo."""
    modo     = r.get("modo", "Alquiler")
    area     = max(float(r.get("area") or 0), 0)
    distrito = r.get("distrito", "Otro")
    clase    = r.get("clase", "B")

    # Benchmarks actualizados Lima 2025 (Cushman & Wakefield / Colliers / mercado real)
    _BNK_ALQ = {
        "San Isidro":  {"A+": 22, "A": 16, "B": 12, "C":  9},
        "Miraflores":  {"A+": 18, "A": 15, "B": 11, "C":  9},
        "San Borja":   {"A+": 16, "A": 13, "B": 10, "C":  8},
        "Surco":       {"A+": 14, "A": 11, "B":  9, "C":  7},
        "La Molina":   {"A+": 13, "A": 10, "B":  8, "C":  6},
        "Jesús María": {"A+": 14, "A": 11, "B":  9, "C":  7},
        "Lince":       {"A+": 13, "A": 10, "B":  8, "C":  6},
        "Magdalena del Mar": {"A+": 13, "A": 10, "B":  8, "C":  6},
        "San Miguel":  {"A+": 12, "A":  9, "B":  7, "C":  6},
    }
    _BNK_PRECIO = {
        "San Isidro":  {"A+": 2800, "A": 2400, "B": 1700, "C": 1200},
        "Miraflores":  {"A+": 2600, "A": 2100, "B": 1500, "C": 1100},
        "San Borja":   {"A+": 2200, "A": 1800, "B": 1400, "C": 1050},
        "Surco":       {"A+": 2000, "A": 1700, "B": 1300, "C": 1000},
        "La Molina":   {"A+": 1900, "A": 1600, "B": 1200, "C":  950},
        "Jesús María": {"A+": 1800, "A": 1500, "B": 1150, "C":  900},
        "Lince":       {"A+": 1700, "A": 1400, "B": 1100, "C":  870},
        "Magdalena del Mar": {"A+": 1700, "A": 1400, "B": 1100, "C": 870},
        "San Miguel":  {"A+": 1600, "A": 1300, "B": 1050, "C":  840},
    }
    _cls = clase if clase in ("A+", "A", "B", "C") else "B"
    _bk_alq    = _BNK_ALQ.get(distrito,    {}).get(_cls, 15)
    _bk_precio = _BNK_PRECIO.get(distrito, {}).get(_cls, 1800)

    # ── MODO ALQUILER ─────────────────────────────────────────────────────
    if modo == "Alquiler":
        alq_base        = max(float(r.get("alq_base") or 0), 0)
        gc_m2           = max(float(r.get("gastos_comunes") or 0), 0)
        cocheras_n      = max(int(r.get("cocheras_n") or 0), 0)
        cocheras_precio = max(float(r.get("cocheras_precio") or 0), 0)
        igv             = bool(r.get("igv", False))
        duracion        = max(float(r.get("duracion") or 1), 0.1)
        garantia        = max(int(r.get("garantia") or 0), 0)
        reajuste_pct    = max(float(r.get("reajuste") or 0), 0) / 100
        gracia          = max(int(r.get("gracia") or 0), 0)

        renta_m2         = alq_base / area if area > 0 else 0
        gc_total_mes     = gc_m2 * area
        cocheras_mes     = cocheras_n * cocheras_precio
        igv_monto        = alq_base * 0.18 if igv else 0
        pago_mensual_renta = alq_base + igv_monto
        pago_mensual_total = pago_mensual_renta + gc_total_mes + cocheras_mes
        garantia_monto   = alq_base * garantia

        duracion_anos    = max(int(duracion), 1)
        costo_total_contrato = 0.0
        gracia_ahorro    = 0.0
        reajuste_proyeccion = []
        for y in range(duracion_anos):
            renta_y = alq_base * (1 + reajuste_pct) ** y
            igv_y   = renta_y * 0.18 if igv else 0
            if y == 0 and gracia > 0:
                grace_m = min(gracia, 12)
                gracia_ahorro = renta_y * grace_m
                costo_r_y = (renta_y + igv_y) * (12 - grace_m)
            else:
                costo_r_y = (renta_y + igv_y) * 12
            costo_yr = costo_r_y + gc_total_mes * 12 + cocheras_mes * 12
            costo_total_contrato += costo_yr
            reajuste_proyeccion.append({
                "año": y + 1,
                "renta_mensual": round(renta_y),
                "pago_mensual":  round((renta_y + igv_y) + gc_total_mes + cocheras_mes),
                "costo_anual":   round(costo_yr),
            })

        diff_bmark = ((renta_m2 - _bk_alq) / _bk_alq * 100) if _bk_alq > 0 else 0
        val_equiv_compra = alq_base * 12 / 0.065 if alq_base > 0 else 0

        return {
            "modo": "Alquiler",
            "renta_m2": round(renta_m2, 1),
            "gc_total_mes": round(gc_total_mes),
            "cocheras_total_mes": round(cocheras_mes),
            "igv_monto": round(igv_monto),
            "pago_mensual_renta": round(pago_mensual_renta),
            "pago_mensual_total": round(pago_mensual_total),
            "garantia_monto": round(garantia_monto),
            "gracia_ahorro": round(gracia_ahorro),
            "costo_total_contrato": round(costo_total_contrato),
            "benchmark_m2": _bk_alq,
            "diff_vs_benchmark_pct": round(diff_bmark, 1),
            "valor_equivalente_compra": round(val_equiv_compra),
            "reajuste_proyeccion": reajuste_proyeccion,
            "duracion_anos": duracion_anos,
        }

    # ── MODO COMPRA ──────────────────────────────────────────────────────
    elif modo == "Compra":
        precio_compra  = max(float(r.get("precio_compra") or 0), 0)
        proposito      = r.get("proposito", "Uso propio")
        alq_esperado   = max(float(r.get("alq_esperado") or 0), 0)
        vacancia_pct_c = max(0.0, min(30.0, float(r.get("vacancia_pct") or 0))) / 100
        alq_efectivo   = alq_esperado * (1 - vacancia_pct_c) if proposito == "Para rentar" else alq_esperado
        pago_ini_pct   = max(float(r.get("pago_inicial_pct") or 30), 10) / 100
        tasa_anual     = max(float(r.get("tasa_anual") or 9), 0) / 100
        plazo_anos     = max(int(r.get("plazo_anos") or 10), 1)
        precio_oferta  = max(float(r.get("precio_oferta") or 0), 0) or precio_compra
        gc_m2          = max(float(r.get("gastos_comunes") or 2.5), 0)

        precio_m2     = precio_compra / area if area > 0 else 0
        pago_inicial  = precio_compra * pago_ini_pct
        monto_credito = precio_compra * (1 - pago_ini_pct)

        cuota_mensual = 0.0
        if monto_credito > 0 and tasa_anual > 0:
            _r = tasa_anual / 12
            _n = plazo_anos * 12
            cuota_mensual = monto_credito * _r * (1 + _r)**_n / ((1 + _r)**_n - 1)

        total_pagado      = pago_inicial + cuota_mensual * plazo_anos * 12
        intereses_totales = total_pagado - precio_compra

        gc_anual    = gc_m2 * area * 12
        noi         = max(alq_efectivo * 12 - gc_anual, 0) if proposito == "Para rentar" else 0
        cap_rate    = (noi / precio_compra * 100)          if precio_compra > 0 and noi > 0 else 0
        yield_bruto = (alq_efectivo * 12 / precio_compra * 100) if precio_compra > 0 and alq_esperado > 0 else 0
        yield_neto  = (noi / precio_compra * 100)          if precio_compra > 0 else 0
        flujo_mensual = (alq_efectivo - cuota_mensual - gc_m2 * area) if proposito == "Para rentar" else 0
        descuento_pct = ((precio_compra - precio_oferta) / precio_compra * 100) if precio_compra > 0 else 0

        diff_precio = ((precio_m2 - _bk_precio) / _bk_precio * 100) if _bk_precio > 0 else 0

        APRECIACION_OFI = 0.04
        flujo_10 = []
        cumul = -pago_inicial
        break_even_ano = None
        for yr in range(1, 11):
            ingresos_yr = alq_efectivo * 12 if proposito == "Para rentar" else 0
            cuota_yr    = cuota_mensual * 12 if yr <= plazo_anos else 0
            flujo_yr    = ingresos_yr - cuota_yr - (gc_anual if proposito == "Para rentar" else 0)
            cumul      += flujo_yr
            if yr == 10:
                val_10 = precio_compra * (1 + APRECIACION_OFI) ** 10
                saldo_deuda = 0.0
                if monto_credito > 0 and tasa_anual > 0 and yr <= plazo_anos:
                    _rm = tasa_anual / 12
                    _np = yr * 12
                    saldo_deuda = max(monto_credito*(1+_rm)**_np - cuota_mensual*((1+_rm)**_np-1)/_rm, 0)
                flujo_yr += val_10 - saldo_deuda
            flujo_10.append({"año": yr, "flujo_anual": round(flujo_yr), "flujo_acumulado": round(cumul)})
            if break_even_ano is None and cumul >= 0 and proposito == "Para rentar":
                break_even_ano = yr

        irr_anual = None
        if proposito == "Para rentar" and alq_esperado > 0:
            _flujos_irr = [-pago_inicial] + [f["flujo_anual"] for f in flujo_10]
            _irr_r = _irr_bisect(_flujos_irr)
            irr_anual = round(_irr_r * 100, 1) if _irr_r is not None else None

        base_dep = precio_compra * 0.60
        depreciacion_anual  = base_dep / 20
        ahorro_fiscal_anual = depreciacion_anual * 0.295
        cuota_efectiva      = max(cuota_mensual - ahorro_fiscal_anual / 12, 0)

        return {
            "modo": "Compra",
            "precio_m2": round(precio_m2),
            "pago_inicial": round(pago_inicial),
            "monto_credito": round(monto_credito),
            "cuota_mensual": round(cuota_mensual),
            "cuota_efectiva": round(cuota_efectiva),
            "total_pagado": round(total_pagado),
            "intereses_totales": round(intereses_totales),
            "noi": round(noi),
            "cap_rate_pct": round(cap_rate, 1),
            "yield_bruto_pct": round(yield_bruto, 1),
            "yield_neto_pct": round(yield_neto, 1),
            "flujo_mensual": round(flujo_mensual),
            "descuento_pct": round(descuento_pct, 1),
            "benchmark_precio_m2": _bk_precio,
            "diff_precio_pct": round(diff_precio, 1),
            "flujo_10": flujo_10,
            "break_even_ano": break_even_ano,
            "irr_anual": irr_anual,
            "proposito": proposito,
            "depreciacion_anual": round(depreciacion_anual),
            "ahorro_fiscal_anual": round(ahorro_fiscal_anual),
            "vacancia_pct": round(vacancia_pct_c * 100, 1),
        }

    # ── MODO DESARROLLO ──────────────────────────────────────────────────
    else:
        area_terreno    = max(float(r.get("area_terreno") or 0), 0)
        precio_terreno  = max(float(r.get("precio_terreno") or 0), 0)
        cus             = max(float(r.get("cus") or 8), 0)
        cos_pct         = max(float(r.get("cos") or 60), 0) / 100
        pisos_oficinas  = max(int(r.get("pisos_oficinas") or 8), 1)
        eficiencia      = max(float(r.get("eficiencia") or 80), 0) / 100
        area_und        = max(float(r.get("area_und") or 200), 50)
        estrategia      = r.get("estrategia", "Venta")
        precio_venta    = max(float(r.get("precio_venta") or 2500), 0)
        precio_alquiler = max(float(r.get("precio_alquiler") or 18), 0)
        vacancia_pct_d  = max(0.0, min(30.0, float(r.get("vacancia_pct") or 0))) / 100
        pct_venta_sl    = max(float(r.get("pct_venta") or 60), 0) / 100
        costo_constr    = max(float(r.get("costo_construccion") or 650), 0)
        costos_ind_pct  = max(float(r.get("costos_ind_pct") or 20), 0) / 100
        costo_sotano_m2 = max(float(r.get("costo_sotano") or 500), 0)
        marketing_pct   = max(float(r.get("marketing_pct") or 3), 0) / 100
        ratio_estac     = max(float(r.get("ratio_estac") or 50), 10)
        dp_terreno_pct  = max(float(r.get("cr_terreno_dp") or 40), 10) / 100
        tasa_terreno    = max(float(r.get("cr_terreno_tasa") or 8), 0) / 100
        plazo_terreno   = max(int(r.get("cr_terreno_plazo") or 10), 1)
        dp_obra_pct     = max(float(r.get("cr_obra_dp") or 30), 10) / 100
        tasa_obra       = max(float(r.get("cr_obra_tasa") or 9), 0) / 100
        plazo_obra      = max(int(r.get("cr_obra_plazo") or 8), 1)

        # Cabida
        area_planta    = area_terreno * cos_pct
        area_bruta     = area_planta * pisos_oficinas
        area_rentable  = area_bruta * eficiencia
        cocheras_total = max(1, int(area_rentable / ratio_estac))
        sotanos        = max(1, int((cocheras_total * 25) / max(area_terreno * 0.90, 1)))
        area_sotanos   = sotanos * area_terreno * 0.90
        unidades       = max(1, int(area_rentable / area_und))

        # Costos
        costo_terreno_total = area_terreno * precio_terreno
        costo_construccion  = area_bruta * costo_constr
        costo_sotanos_t     = area_sotanos * costo_sotano_m2
        costos_directos     = costo_construccion + costo_sotanos_t
        costos_indirectos   = costos_directos * costos_ind_pct
        alcabala            = costo_terreno_total * 0.03

        # Ingresos por estrategia
        if estrategia == "Venta":
            area_venta = area_rentable; area_renta = 0.0
        elif estrategia == "Renta":
            area_venta = 0.0; area_renta = area_rentable
        else:
            area_venta = area_rentable * pct_venta_sl
            area_renta = area_rentable * (1 - pct_venta_sl)

        ingresos_venta          = area_venta * precio_venta
        renta_anual             = area_renta * precio_alquiler * 12 * (1 - vacancia_pct_d)
        CAP_RATE_OFI            = 0.075
        valor_renta_capitalizado = renta_anual / CAP_RATE_OFI if renta_anual > 0 else 0
        ingresos_totales        = ingresos_venta + valor_renta_capitalizado
        costo_marketing         = ingresos_totales * marketing_pct
        costo_total             = costo_terreno_total + alcabala + costos_directos + costos_indirectos + costo_marketing

        utilidad_bruta  = ingresos_totales - costo_total
        margen_bruto    = (utilidad_bruta / ingresos_totales * 100) if ingresos_totales > 0 else 0
        # IGV primera venta: base imponible = precio_venta - valor_terreno (SUNAT/IGV Art. 1)
        igv_ventas      = max(0, ingresos_venta - costo_terreno_total) * 0.18
        utilidad_neta   = utilidad_bruta - igv_ventas
        margen_neto     = (utilidad_neta / ingresos_totales * 100) if ingresos_totales > 0 else 0

        # Créditos
        cap_terreno    = costo_terreno_total * dp_terreno_pct
        credito_terreno = costo_terreno_total * (1 - dp_terreno_pct)
        cuota_terreno  = 0.0
        if credito_terreno > 0 and tasa_terreno > 0:
            _rt = tasa_terreno / 12; _nt = plazo_terreno * 12
            cuota_terreno = credito_terreno * _rt * (1+_rt)**_nt / ((1+_rt)**_nt - 1)
        cap_obra     = costos_directos * dp_obra_pct
        credito_obra = costos_directos * (1 - dp_obra_pct)
        cuota_obra   = 0.0
        if credito_obra > 0 and tasa_obra > 0:
            _ro = tasa_obra / 12; _no = plazo_obra * 12
            cuota_obra = credito_obra * _ro * (1+_ro)**_no / ((1+_ro)**_no - 1)

        capital_propio     = cap_terreno + cap_obra + costos_indirectos + costo_marketing
        deuda_total        = credito_terreno + credito_obra
        cuota_mensual      = cuota_terreno + cuota_obra
        pct_apalancamiento = (deuda_total / costo_total * 100) if costo_total > 0 else 0
        roi                = (utilidad_neta / capital_propio * 100) if capital_propio > 0 else 0

        # TIR — inversión distribuida 24 meses + retorno al final
        MESES_CONSTR = 24
        _equity_m = capital_propio / MESES_CONSTR
        _flujos_tir = [-_equity_m] * MESES_CONSTR + [utilidad_neta + capital_propio]
        _irr_m = _irr_bisect(_flujos_tir)
        tir_anual = round(((1 + _irr_m)**12 - 1) * 100, 1) if _irr_m is not None else None

        # Escenarios
        def _esc(dv, dc):
            _pv = precio_venta * (1 + dv)
            _iv = area_venta * _pv
            _rv = renta_anual / CAP_RATE_OFI if renta_anual > 0 else 0
            _it = _iv + _rv
            _cd = area_bruta * costo_constr * (1 + dc) + costo_sotanos_t
            _ct = costo_terreno_total + alcabala + _cd + _cd * costos_ind_pct + _it * marketing_pct
            _un = (_it - _ct) - _iv * 0.18
            _mg = ((_it - _ct) / _it * 100) if _it > 0 else 0
            _roi = (_un / capital_propio * 100) if capital_propio > 0 else 0
            return {"margen": round(_mg, 1), "utilidad": round(_un), "roi": round(_roi, 1)}

        return {
            "modo": "Desarrollo",
            "area_planta": round(area_planta), "area_bruta": round(area_bruta),
            "area_rentable": round(area_rentable), "unidades": unidades,
            "cocheras_total": cocheras_total, "sotanos": sotanos,
            "costo_terreno_total": round(costo_terreno_total), "alcabala": round(alcabala),
            "costos_directos": round(costos_directos), "costos_indirectos": round(costos_indirectos),
            "costo_marketing": round(costo_marketing), "costo_total": round(costo_total),
            "ingresos_venta": round(ingresos_venta), "renta_anual": round(renta_anual),
            "valor_renta_capitalizado": round(valor_renta_capitalizado),
            "ingresos_totales": round(ingresos_totales),
            "utilidad_bruta": round(utilidad_bruta), "margen_bruto_pct": round(margen_bruto, 1),
            "igv_ventas": round(igv_ventas),
            "utilidad_neta": round(utilidad_neta), "margen_neto_pct": round(margen_neto, 1),
            "roi_pct": round(roi, 1), "tir_anual_pct": tir_anual,
            "capital_propio": round(capital_propio), "deuda_total": round(deuda_total),
            "cuota_mensual": round(cuota_mensual), "pct_apalancamiento": round(pct_apalancamiento, 1),
            "cap_terreno": round(cap_terreno), "credito_terreno": round(credito_terreno),
            "cuota_terreno": round(cuota_terreno),
            "cap_obra": round(cap_obra), "credito_obra": round(credito_obra),
            "cuota_obra": round(cuota_obra),
            "estrategia": estrategia,
            "esc_pesimista": _esc(-0.10, +0.08),
            "esc_base":      _esc(0,      0),
            "esc_optimista": _esc(+0.08, -0.05),
            "vacancia_pct": round(vacancia_pct_d * 100, 1),
        }


# ═══════════════════════════════════════════════════════
# ANÁLISIS RETAIL / LOCAL COMERCIAL
# ═══════════════════════════════════════════════════════

def calcular_retail(inp: dict) -> dict:
    """Modelo financiero para activos retail / locales comerciales en Lima."""
    area_gla          = float(inp.get("area_gla", 0) or 0)
    area_total        = float(inp.get("area_total", 0) or 0)
    costo_terreno     = float(inp.get("costo_terreno", 0) or 0)
    costo_construccion_m2 = float(inp.get("costo_construccion_m2", 1200) or 1200)
    modo              = inp.get("modo", "Inversión")
    formato           = inp.get("formato", "Local en Avenida")
    renta_m2_mes      = float(inp.get("renta_m2_mes", 0) or 0)
    vacancia_pct      = float(inp.get("vacancia_pct", 8.0) or 8.0)
    opex_pct          = float(inp.get("opex_pct", 20.0) or 20.0)
    include_alcabala  = inp.get("include_alcabala", True)
    reajuste_anual_pct = float(inp.get("reajuste_anual_pct", 3.0) or 3.0)
    duracion_anos     = int(inp.get("duracion_anos", 3) or 3)
    gastos_comunes_m2 = float(inp.get("gastos_comunes_m2", 0.0) or 0.0)
    hurdle_rate_pct   = float(inp.get("hurdle_rate_pct", 10.0) or 10.0)
    cap_rate_mercado_pct = float(inp.get("cap_rate_mercado_pct", 8.0) or 8.0)
    ocr_referencial_pct = float(inp.get("ocr_referencial_pct", 10.0) or 10.0)

    # ── Costos (solo para Inversión / Desarrollo) ────────
    if modo == "Arrendatario":
        alcabala = 0.0
        costo_construccion_total = 0.0
        pct_indirectos_v = 0.0
        soft_costs = 0.0
        costo_total = 0.0
        costo_por_m2_gla = 0.0
        eficiencia_gla = (area_gla / area_total * 100) if area_total > 0 else 0.0
    else:
        alcabala = costo_terreno * 0.03 if include_alcabala else 0.0
        costo_construccion_total = area_total * costo_construccion_m2
        pct_indirectos_v = float(inp.get("pct_indirectos", 8.0) or 8.0) / 100
        soft_costs = costo_construccion_total * pct_indirectos_v
        costo_total = costo_terreno + alcabala + costo_construccion_total + soft_costs
        costo_por_m2_gla = costo_total / area_gla if area_gla > 0 else 0.0
        eficiencia_gla = (area_gla / area_total * 100) if area_total > 0 else 0.0

    # ── NOI y métricas ───────────────────────────────────
    renta_bruta_mes = renta_m2_mes * area_gla
    renta_bruta_anual = renta_bruta_mes * 12 * (1 - vacancia_pct / 100)
    opex_anual = renta_bruta_anual * (opex_pct / 100)
    noi = renta_bruta_anual - opex_anual
    yield_bruto = (renta_bruta_anual / costo_total * 100) if costo_total > 0 else 0.0
    yield_neto  = (noi / costo_total * 100) if costo_total > 0 else 0.0
    cap_rate    = yield_neto
    valor_por_cap_rate = (noi / (cap_rate_mercado_pct / 100)) if cap_rate_mercado_pct > 0 else 0.0
    ventas_implicitas_m2_ano = (renta_m2_mes * 12 / (ocr_referencial_pct / 100)) if ocr_referencial_pct > 0 else 0.0
    payback_anos = (costo_total / noi) if noi > 0 and costo_total > 0 else None

    # ── Financiamiento (dos créditos independientes) ─────
    dp_terreno_pct = max(0.0, min(100.0, float(inp.get("dp_terreno_pct", 40.0) or 40.0)))
    tasa_terreno   = float(inp.get("tasa_terreno",  8.0) or 8.0) / 100
    plazo_terreno  = max(int(inp.get("plazo_terreno", 10) or 10), 1)
    dp_const_pct   = max(0.0, min(100.0, float(inp.get("dp_const_pct",  30.0) or 30.0)))
    tasa_const     = float(inp.get("tasa_const",   9.0) or 9.0) / 100
    plazo_const    = max(int(inp.get("plazo_const",   8) or 8), 1)

    costo_terreno_alc = costo_terreno + alcabala
    capital_propio_terreno = costo_terreno_alc * (dp_terreno_pct / 100)
    monto_credito_terreno  = costo_terreno_alc * (1 - dp_terreno_pct / 100)
    cuota_terreno = 0.0
    if monto_credito_terreno > 0 and tasa_terreno > 0:
        _rt = tasa_terreno / 12
        _nt = plazo_terreno * 12
        cuota_terreno = monto_credito_terreno * _rt * (1 + _rt)**_nt / ((1 + _rt)**_nt - 1)

    costo_const_soft = costo_construccion_total + soft_costs
    capital_propio_const = costo_const_soft * (dp_const_pct / 100)
    monto_credito_const  = costo_const_soft * (1 - dp_const_pct / 100)
    cuota_const = 0.0
    if monto_credito_const > 0 and tasa_const > 0:
        _rc = tasa_const / 12
        _nc = plazo_const * 12
        cuota_const = monto_credito_const * _rc * (1 + _rc)**_nc / ((1 + _rc)**_nc - 1)

    capital_propio = capital_propio_terreno + capital_propio_const
    monto_credito  = monto_credito_terreno  + monto_credito_const
    cuota_mensual  = cuota_terreno          + cuota_const
    flujo_mensual_neto = noi / 12 - cuota_mensual if cuota_mensual > 0 else noi / 12
    dscr = (noi / (cuota_mensual * 12)) if (cuota_mensual > 0 and noi > 0) else 0.0

    # ── IRR a 10 años (solo Inversión con capital propio) ──
    flujo_anual = []
    irr_anual   = None
    van_10      = None
    tasa_desc   = max(hurdle_rate_pct, 1.0) / 100
    APRECIACION_RETAIL = 0.03

    if modo in ("Inversión", "Desarrollo") and noi > 0 and capital_propio > 0:
        flujo_anual = [-capital_propio]
        for yr in range(1, 11):
            cuota_yr = 0.0
            if yr <= plazo_terreno:
                cuota_yr += cuota_terreno * 12
            if yr <= plazo_const:
                cuota_yr += cuota_const * 12
            noi_yr = noi * (1 + reajuste_anual_pct / 100) ** (yr - 1)
            flujo_yr = noi_yr - cuota_yr
            if yr == 10:
                saldo_deuda = 0.0
                if monto_credito_terreno > 0 and tasa_terreno > 0 and yr <= plazo_terreno:
                    _r_t = tasa_terreno / 12
                    _n_t = yr * 12
                    saldo_deuda += max(
                        monto_credito_terreno * (1 + _r_t)**_n_t
                        - cuota_terreno * ((1 + _r_t)**_n_t - 1) / _r_t, 0)
                if monto_credito_const > 0 and tasa_const > 0 and yr <= plazo_const:
                    _r_c = tasa_const / 12
                    _n_c = yr * 12
                    saldo_deuda += max(
                        monto_credito_const * (1 + _r_c)**_n_c
                        - cuota_const * ((1 + _r_c)**_n_c - 1) / _r_c, 0)
                flujo_yr += costo_total * (1 + APRECIACION_RETAIL)**10 - saldo_deuda
            flujo_anual.append(flujo_yr)
        irr_r = _irr_bisect(flujo_anual)
        irr_anual = round(irr_r * 100, 1) if irr_r is not None else None
        van_10 = sum(f / (1 + tasa_desc)**i for i, f in enumerate(flujo_anual))

    # ── Modo Arrendatario ────────────────────────────────
    costo_mensual_total = (renta_m2_mes + gastos_comunes_m2) * area_gla
    costo_anual_total   = costo_mensual_total * 12
    proyeccion_anos = []
    if modo == "Arrendatario":
        for yr in range(1, duracion_anos + 1):
            factor = (1 + reajuste_anual_pct / 100) ** (yr - 1)
            proyeccion_anos.append({
                "año": yr,
                "renta_m2": round(renta_m2_mes * factor, 2),
                "total_anual": round(costo_mensual_total * factor * 12, 0),
            })

    return {
        "modo": modo, "formato": formato,
        "area_gla": area_gla, "area_total": area_total, "eficiencia_gla": round(eficiencia_gla, 1),
        "costo_terreno": costo_terreno, "alcabala": alcabala,
        "costo_construccion_total": costo_construccion_total,
        "costo_construccion_m2": costo_construccion_m2,
        "soft_costs": soft_costs, "pct_indirectos": pct_indirectos_v * 100,
        "costo_total": costo_total, "costo_por_m2_gla": round(costo_por_m2_gla, 0),
        "renta_m2_mes": renta_m2_mes, "renta_bruta_mes": renta_bruta_mes,
        "renta_bruta_anual": renta_bruta_anual,
        "vacancia_pct": vacancia_pct, "opex_pct": opex_pct,
        "opex_anual": opex_anual, "noi": noi,
        "yield_bruto": round(yield_bruto, 2), "yield_neto": round(yield_neto, 2),
        "cap_rate": round(cap_rate, 2),
        "cap_rate_mercado_pct": cap_rate_mercado_pct,
        "valor_por_cap_rate": round(valor_por_cap_rate, 0),
        "ocr_referencial_pct": ocr_referencial_pct,
        "ventas_implicitas_m2_ano": round(ventas_implicitas_m2_ano, 0),
        "payback_anos": payback_anos,
        # Financiamiento
        "capital_propio": round(capital_propio, 0),
        "monto_credito": round(monto_credito, 0),
        "cuota_mensual": round(cuota_mensual, 0),
        "dscr": round(dscr, 2),
        "capital_propio_terreno": round(capital_propio_terreno, 0),
        "monto_credito_terreno":  round(monto_credito_terreno, 0),
        "cuota_terreno": round(cuota_terreno, 0),
        "dp_terreno_pct": dp_terreno_pct,
        "tasa_terreno": tasa_terreno * 100,
        "plazo_terreno": plazo_terreno,
        "capital_propio_const": round(capital_propio_const, 0),
        "monto_credito_const":  round(monto_credito_const, 0),
        "cuota_const": round(cuota_const, 0),
        "dp_const_pct": dp_const_pct,
        "tasa_const": tasa_const * 100,
        "plazo_const": plazo_const,
        "flujo_mensual_neto": round(flujo_mensual_neto, 0),
        # IRR / VAN
        "flujo_anual": flujo_anual,
        "irr_anual": irr_anual,
        "van_10": round(van_10, 0) if van_10 is not None else None,
        "hurdle_rate_pct": hurdle_rate_pct,
        "reajuste_anual_pct": reajuste_anual_pct,
        # Arrendatario
        "costo_mensual_total": round(costo_mensual_total, 0),
        "costo_anual_total": round(costo_anual_total, 0),
        "proyeccion_anos": proyeccion_anos,
        "gastos_comunes_m2": gastos_comunes_m2,
        "duracion_anos": duracion_anos,
        "actividad": inp.get("actividad", ""),
        "zonificacion": inp.get("zonificacion", "CZ"),
    }


# ═══════════════════════════════════════════════════════
# ANÁLISIS LOGÍSTICO / INDUSTRIAL
# ═══════════════════════════════════════════════════════

def calcular_industrial(inp: dict) -> dict:
    area = inp.get("area_terreno", 0)
    costo_terreno = inp.get("costo_terreno", 0)
    tipo_nave = inp.get("tipo_nave", "Almacén Logístico")
    zonificacion = inp.get("zonificacion", "I2")
    uso = inp.get("uso", "Uso directo")

    # Área techada / libre según porcentaje definido por usuario
    pct_techada = max(min(inp.get("pct_techada", 75), 95), 30) / 100
    area_nave = area * pct_techada          # nave techada
    area_libre = area * (1 - pct_techada)   # patios, maniobras, circulación

    # Costos de construcción — usuario puede sobreescribir con su propio dato.
    # Defaults diferenciados por zona y tipo (Lima 2025):
    #   · VES / SJL / SMP: nave estándar 10-12m → $300/m² (ref. Parque Logístico 47: $291.5/m²)
    #   · Lurín Clase A (12-15m, sprinklers): $480/m² (mid Cushman & Wakefield mayo 2026: $430-650)
    #   · Otras zonas: $350/m² (punto medio prudente)
    #   · Cross-docking (múltiples docks, losa reforzada): $420/m²
    #   · Producción / Manufactura (losa reforzada): $400/m²
    # Detectar zona por ubicación/distrito (campo "ubicacion" o "zona_ind")
    _ub_lower   = str(inp.get("ubicacion", "") or inp.get("zona_ind", "") or "").lower()
    _es_lurin   = "lurín" in _ub_lower or "lurin" in _ub_lower
    _es_ves_sjl = any(x in _ub_lower for x in ("ves", "villa el salvador", "sjl", "san juan", "smp", "san martín", "san martin", "huachipa"))
    _DEFAULTS_NAVE = {
        "Almacén Logístico":        480 if _es_lurin else (300 if _es_ves_sjl else 350),
        "Nave Industrial":          480 if _es_lurin else (300 if _es_ves_sjl else 350),
        "Cross-docking":            420,
        "Producción / Manufactura": 400,
    }
    _default_nave = _DEFAULTS_NAVE.get(tipo_nave, 350)
    _cn = inp.get("costo_nave_m2")
    costo_nave_m2 = _cn if _cn is not None else _default_nave
    _cp = inp.get("costo_piso_libre_m2")
    costo_piso_libre_m2 = _cp if _cp is not None else 80

    costo_nave_total = area_nave * costo_nave_m2
    costo_pisos_libres = area_libre * costo_piso_libre_m2
    costo_construccion = costo_nave_total + costo_pisos_libres
    pct_indirectos = inp.get("pct_indirectos", 5.0) / 100
    soft_costs = costo_construccion * pct_indirectos
    alcabala = costo_terreno * 0.03 if inp.get("include_alcabala", True) else 0
    costo_total = costo_terreno + alcabala + costo_construccion + soft_costs
    costo_por_m2_nave = costo_total / area_nave if area_nave > 0 else 0

    # ── Crédito Terreno ──────────────────────────────────────
    costo_terreno_alcabala = costo_terreno + alcabala
    dp_terreno_pct = max(0.0, min(100.0, inp.get("dp_terreno_pct", 40.0))) / 100
    capital_propio_terreno = costo_terreno_alcabala * dp_terreno_pct
    monto_credito_terreno  = costo_terreno_alcabala * (1 - dp_terreno_pct)
    tasa_terreno  = inp.get("tasa_terreno",  8.0) / 100
    plazo_terreno = max(inp.get("plazo_terreno", 10), 1)
    cuota_terreno = 0.0
    if monto_credito_terreno > 0 and tasa_terreno > 0:
        _rt = tasa_terreno / 12
        _nt = plazo_terreno * 12
        cuota_terreno = monto_credito_terreno * _rt * (1 + _rt)**_nt / ((1 + _rt)**_nt - 1)

    # ── Crédito Construcción ─────────────────────────────────
    costo_construccion_soft = costo_construccion + soft_costs
    dp_const_pct = max(0.0, min(100.0, inp.get("dp_const_pct", 30.0))) / 100
    capital_propio_const = costo_construccion_soft * dp_const_pct
    monto_credito_const  = costo_construccion_soft * (1 - dp_const_pct)
    tasa_const  = inp.get("tasa_const",  9.0) / 100
    plazo_const = max(inp.get("plazo_const", 8), 1)
    cuota_const = 0.0
    if monto_credito_const > 0 and tasa_const > 0:
        _rc = tasa_const / 12
        _nc = plazo_const * 12
        cuota_const = monto_credito_const * _rc * (1 + _rc)**_nc / ((1 + _rc)**_nc - 1)

    # ── Totales combinados ───────────────────────────────────
    capital_propio = capital_propio_terreno + capital_propio_const
    monto_credito  = monto_credito_terreno  + monto_credito_const
    cuota_mensual  = cuota_terreno          + cuota_const
    pct_credito    = (monto_credito / costo_total * 100) if costo_total > 0 else 0
    plazo_anos     = max(plazo_terreno, plazo_const)
    # Promedio ponderado por monto de cada crédito (más preciso que promedio aritmético)
    _mc_tot = monto_credito_terreno + monto_credito_const
    tasa_anual = ((tasa_terreno * monto_credito_terreno + tasa_const * monto_credito_const) / _mc_tot
                  if _mc_tot > 0 else (tasa_terreno + tasa_const) / 2)

    # Renta base sobre área techada (nave arrendable)
    renta_m2_mes = inp.get("renta_m2_mes", 0)
    vacancia_pct_ind = max(0.0, min(30.0, inp.get("vacancia_pct", 0.0))) / 100
    # vacancy_schedule: dict opcional de vacancia por año {1: 0.30, 2: 0.15}
    # Si no se provee, usa vacancia fija para todos los años (comportamiento previo)
    _vac_sched_raw = inp.get("vacancy_schedule") or {}
    _vac_sched = {int(k): max(0.0, min(1.0, float(v))) for k, v in _vac_sched_raw.items()} if _vac_sched_raw else {}

    def _vacancia_ano(yr: int) -> float:
        return _vac_sched.get(yr, vacancia_pct_ind)

    renta_total_mes = renta_m2_mes * area_nave * (1 - _vacancia_ano(1))
    gastos_operacion = renta_total_mes * 12 * 0.08
    renta_neta_anual = max(renta_total_mes * 12 - gastos_operacion, 0)
    yield_bruto = (renta_total_mes * 12 / costo_total * 100) if costo_total > 0 else 0
    yield_neto = (renta_neta_anual / costo_total * 100) if costo_total > 0 else 0
    payback_anos = (costo_total / renta_neta_anual) if renta_neta_anual > 0 else None
    flujo_mensual = renta_total_mes - cuota_mensual if uso == "Inversión" else None
    # DSCR correcto banco: NOI anual / servicio de deuda anual (no gross rent / cuota mensual)
    dscr = (renta_neta_anual / (cuota_mensual * 12)) if (cuota_mensual > 0 and renta_neta_anual > 0) else None
    alquiler_vs_compra = renta_total_mes - cuota_mensual if uso == "Uso directo" else None

    # ── Indexación de renta por contrato plurianual ──
    tipo_contrato_ind    = inp.get("tipo_contrato", "Anual")
    ajuste_anual_ind_pct = inp.get("ajuste_anual_pct", 0.0) / 100
    inicio_ajuste_ind    = int(inp.get("inicio_ajuste_ano", 2))
    _es_plurianual_ind   = tipo_contrato_ind != "Anual" and ajuste_anual_ind_pct > 0

    def _renta_neta_ind(yr):
        """Renta neta anual del año yr con ajuste contractual y vacancia variable."""
        _vac_yr = _vacancia_ano(yr)
        _renta_base_mes = renta_m2_mes * area_nave * (1 - _vac_yr)
        if not _es_plurianual_ind or yr < inicio_ajuste_ind:
            return max(_renta_base_mes * 12 * (1 - 0.08), 0)
        factor = (1 + ajuste_anual_ind_pct) ** (yr - inicio_ajuste_ind + 1)
        return max(_renta_base_mes * factor * 12 * (1 - 0.08), 0)

    # Proyecciones año 3 y 5 (renta mensual/m² y yield)
    _rn3 = _renta_neta_ind(3)
    _rn5 = _renta_neta_ind(5)
    renta_m2_ano3  = (_rn3 / 12 / area_nave) if area_nave > 0 else 0
    renta_m2_ano5  = (_rn5 / 12 / area_nave) if area_nave > 0 else 0
    yield_neto_ano3 = (_rn3 / costo_total * 100) if costo_total > 0 else 0
    yield_neto_ano5 = (_rn5 / costo_total * 100) if costo_total > 0 else 0

    # Payback indexado (años para recuperar inversión con renta creciente)
    payback_indexado_ind = None
    if _es_plurianual_ind and renta_neta_anual > 0:
        _acum = 0.0
        for _y in range(1, 41):
            _acum += _renta_neta_ind(_y)
            if _acum >= costo_total:
                payback_indexado_ind = _y
                break

    # ── Escudo fiscal por depreciación de la nave (Perú: 5%/año, 20 años, IR 29.5%) ──
    VIDA_UTIL_NAVE = 20        # años de vida útil tributaria (DS 122-94-EF)
    TASA_IR = 0.295            # Impuesto a la Renta corporativo Perú
    depreciacion_anual = costo_nave_total / VIDA_UTIL_NAVE   # base: solo la nave, no el terreno
    ahorro_fiscal_anual = depreciacion_anual * TASA_IR       # ahorro en IR por depreciación
    ahorro_fiscal_mensual = ahorro_fiscal_anual / 12
    # Costo efectivo mensual de compra para Uso directo (cuota – escudo fiscal)
    cuota_efectiva_mensual = max(cuota_mensual - ahorro_fiscal_mensual, 0)

    # ── IRR y flujo de caja anual (10 años, solo inversión) ──
    flujo_anual = []
    irr_anual = None
    van_10 = None
    # Hurdle rate configurable — tasa de descuento del inversionista (default 10% Lima industrial)
    tasa_desc = max(float(inp.get("hurdle_rate_pct", 10.0)), 1.0) / 100
    APRECIACION_IND = 0.03

    if uso == "Inversión" and renta_neta_anual > 0 and capital_propio > 0:
        flujo_anual = [-capital_propio]
        for yr in range(1, 11):
            # Cuota anual correcta: cada crédito se detiene en su propio plazo
            cuota_yr = 0
            if yr <= plazo_terreno:
                cuota_yr += cuota_terreno * 12
            if yr <= plazo_const:
                cuota_yr += cuota_const * 12
            flujo_yr = _renta_neta_ind(yr) - cuota_yr
            if yr == 10:
                # Saldo residual calculado por crédito con su tasa y plazo propios
                saldo_deuda = 0
                if monto_credito_terreno > 0 and tasa_terreno > 0 and yr <= plazo_terreno:
                    _r_t = tasa_terreno / 12
                    _n_t = yr * 12
                    saldo_deuda += max(
                        monto_credito_terreno * (1+_r_t)**_n_t
                        - cuota_terreno * ((1+_r_t)**_n_t - 1) / _r_t, 0)
                if monto_credito_const > 0 and tasa_const > 0 and yr <= plazo_const:
                    _r_c = tasa_const / 12
                    _n_c = yr * 12
                    saldo_deuda += max(
                        monto_credito_const * (1+_r_c)**_n_c
                        - cuota_const * ((1+_r_c)**_n_c - 1) / _r_c, 0)
                flujo_yr += costo_total * (1 + APRECIACION_IND)**10 - saldo_deuda
            flujo_anual.append(flujo_yr)
        irr_r = _irr_bisect(flujo_anual)
        irr_anual = round(irr_r * 100, 1) if irr_r is not None else None
        van_10 = sum(f / (1 + tasa_desc)**i for i, f in enumerate(flujo_anual))

    # ── Análisis de densidad de rack ──────────────────────────────────────────
    _h_nave     = inp.get("altura_nave", 0.0) or 0.0
    rack_niveles = max(1, int(_h_nave / 1.70)) if _h_nave >= 3.0 else 0
    rack_pos_m2  = round(rack_niveles * 0.227, 2)           # pos/m² rack estándar (validado: 12m→1.59)
    rack_posiciones     = round(rack_pos_m2 * area_nave)
    rack_posiciones_opt = round(2.03 * area_nave)            # 13.6m, sistema Aldea (Francis de la Croix)
    rack_delta_pos  = rack_posiciones_opt - rack_posiciones
    rack_delta_pct  = round((rack_posiciones_opt / rack_posiciones - 1) * 100, 1) if rack_posiciones > 0 else 0.0
    rack_es_optima  = _h_nave >= 13.5

    return {
        "area_terreno": area,
        "area_nave": area_nave, "area_libre": area_libre, "pct_techada": pct_techada * 100,
        "costo_terreno": costo_terreno, "alcabala": alcabala,
        "costo_nave_total": costo_nave_total, "costo_pisos_libres": costo_pisos_libres,
        "costo_construccion": costo_construccion, "soft_costs": soft_costs,
        "pct_indirectos": pct_indirectos * 100,
        "costo_total": costo_total, "costo_por_m2_nave": costo_por_m2_nave,
        "costo_nave_m2": costo_nave_m2, "costo_piso_libre_m2": costo_piso_libre_m2,
        "monto_credito": monto_credito, "capital_propio": capital_propio,
        "cuota_mensual": cuota_mensual, "pct_credito": pct_credito, "plazo_anos": plazo_anos,
        "tasa_anual": tasa_anual * 100,
        # Desglose terreno
        "costo_terreno_alcabala": costo_terreno_alcabala,
        "capital_propio_terreno": capital_propio_terreno,
        "monto_credito_terreno":  monto_credito_terreno,
        "cuota_terreno":          cuota_terreno,
        "dp_terreno_pct":         dp_terreno_pct * 100,
        "tasa_terreno":           tasa_terreno * 100,
        "plazo_terreno":          plazo_terreno,
        # Desglose construcción
        "costo_construccion_soft": costo_construccion_soft,
        "capital_propio_const":    capital_propio_const,
        "monto_credito_const":     monto_credito_const,
        "cuota_const":             cuota_const,
        "dp_const_pct":            dp_const_pct * 100,
        "tasa_const":              tasa_const * 100,
        "plazo_const":             plazo_const,
        "renta_m2_mes": renta_m2_mes, "renta_total_mes": renta_total_mes,
        "vacancia_pct": round(vacancia_pct_ind * 100, 1),
        "vacancy_schedule": {str(k): round(v * 100, 1) for k, v in _vac_sched.items()},
        "flujo_anual_detalle": [
            {
                "ano": yr,
                "vacancia_pct": round(_vacancia_ano(yr) * 100, 1),
                "renta_neta": round(_renta_neta_ind(yr)),
            }
            for yr in range(1, 11)
        ] if uso == "Inversión" and renta_m2_mes > 0 else [],
        "gastos_operacion": gastos_operacion, "renta_neta_anual": renta_neta_anual,
        "yield_bruto": yield_bruto, "yield_neto": yield_neto,
        "payback_anos": payback_anos, "flujo_mensual": flujo_mensual,
        "dscr": dscr, "alquiler_vs_compra": alquiler_vs_compra,
        "flujo_anual": flujo_anual, "irr_anual": irr_anual, "van_10": van_10,
        "hurdle_rate_pct": round(tasa_desc * 100, 1),
        "tipo_nave": tipo_nave, "zonificacion": zonificacion, "uso": uso,
        "altura_nave": inp.get("altura_nave", 0.0),
        "actividad_categoria": inp.get("actividad_categoria", ""),
        "actividad_descripcion": inp.get("actividad_descripcion", ""),
        # Escudo fiscal
        "depreciacion_anual": round(depreciacion_anual),
        "ahorro_fiscal_anual": round(ahorro_fiscal_anual),
        "ahorro_fiscal_mensual": round(ahorro_fiscal_mensual),
        "cuota_efectiva_mensual": round(cuota_efectiva_mensual),
        "APRECIACION_IND": APRECIACION_IND,
        # Indexación contractual
        "tipo_contrato": tipo_contrato_ind,
        "ajuste_anual_pct": round(ajuste_anual_ind_pct * 100, 2),
        "inicio_ajuste_ano": inicio_ajuste_ind,
        "renta_m2_ano3": round(renta_m2_ano3, 2),
        "renta_m2_ano5": round(renta_m2_ano5, 2),
        "yield_neto_ano3": round(yield_neto_ano3, 1),
        "yield_neto_ano5": round(yield_neto_ano5, 1),
        "payback_indexado": payback_indexado_ind,
        # Rack density
        "rack_niveles": rack_niveles,
        "rack_pos_m2": rack_pos_m2,
        "rack_posiciones": rack_posiciones,
        "rack_posiciones_opt": rack_posiciones_opt,
        "rack_delta_pos": rack_delta_pos,
        "rack_delta_pct": rack_delta_pct,
        "rack_es_optima": rack_es_optima,
        "perfil": inp.get("perfil", "Desarrollo Integral"),
    }


@st.cache_data(show_spinner=False)
def calcular_sensibilidad_industrial(base_inp: dict):
    """Matriz 5×5: yield bruto % + IRR equity % cruzando renta/m²/mes × precio terreno/m².
    Filas = precio terreno/m² (±30%), Cols = renta/m²/mes (±20%).
    Returns (grid_yield, grid_irr, rentas, terrenos_m2, renta_base, terreno_m2_base) or None.
    """
    renta_base   = base_inp.get("renta_m2_mes", 0)
    costo_t_base = base_inp.get("costo_terreno", 0)
    area         = base_inp.get("area_terreno", 0)
    if renta_base <= 0 or costo_t_base <= 0 or area <= 0:
        return None

    terreno_m2_base = costo_t_base / area

    pct_r = [-20, -10, 0, 10, 20]
    rentas = [max(0.5, round(renta_base * (1 + p / 100) * 4) / 4) for p in pct_r]

    pct_t = [-30, -15, 0, 15, 30]
    terrenos_m2 = [max(50, round(terreno_m2_base * (1 + t / 100) / 50) * 50) for t in pct_t]

    grid_yield = []
    grid_irr   = []
    for tm2 in terrenos_m2:
        row_y = []; row_i = []
        for rm2 in rentas:
            inp_adj = {**base_inp, "renta_m2_mes": rm2, "costo_terreno": tm2 * area}
            res = calcular_industrial(inp_adj)
            row_y.append(res["yield_bruto"])
            row_i.append(res["irr_anual"])
        grid_yield.append(row_y)
        grid_irr.append(row_i)

    return grid_yield, grid_irr, rentas, terrenos_m2, renta_base, terreno_m2_base


# ═══════════════════════════════════════════════════════
# ANÁLISIS RESIDENCIAL
# ═══════════════════════════════════════════════════════

def calcular_residencial(inp: dict) -> dict:
    precio = inp.get("precio", 0)
    pct_pie = max(min(inp.get("pct_pie", 20), 100), 0) / 100
    tasa_anual = inp.get("tasa_anual", 8.5) / 100
    plazo_anos = max(inp.get("plazo_anos", 20), 1)
    uso = inp.get("uso", "Vivienda propia")

    pie = precio * pct_pie
    monto_credito = precio * (1 - pct_pie)
    cuota_mensual = 0.0
    total_pagado = precio
    total_intereses = 0.0
    n_meses = plazo_anos * 12

    if monto_credito > 0 and tasa_anual > 0:
        r = tasa_anual / 12
        n = n_meses
        cuota_mensual = monto_credito * r * (1 + r)**n / ((1 + r)**n - 1)
        total_pagado = pie + cuota_mensual * n
        total_intereses = total_pagado - precio

    ingreso_minimo = cuota_mensual / 0.30 if cuota_mensual > 0 else 0

    alquiler_mes = inp.get("alquiler_mes", 0)
    gastos_mes = inp.get("gastos_mes", 0)
    renta_neta_mes = max(alquiler_mes - gastos_mes, 0)
    yield_bruto = (alquiler_mes * 12 / precio * 100) if precio > 0 else 0
    yield_neto = (renta_neta_mes * 12 / precio * 100) if precio > 0 else 0
    payback_anos = (precio / (renta_neta_mes * 12)) if renta_neta_mes > 0 else None
    flujo_mensual = renta_neta_mes - cuota_mensual if uso == "Inversión" else None
    alquiler_equilibrio = cuota_mensual + gastos_mes

    # ── Indexación de renta por contrato plurianual ──
    tipo_contrato_res    = inp.get("tipo_contrato", "Anual")
    ajuste_anual_res_pct = inp.get("ajuste_anual_pct", 0.0) / 100
    inicio_ajuste_res    = int(inp.get("inicio_ajuste_ano", 2))
    _es_plurianual_res   = tipo_contrato_res != "Anual" and ajuste_anual_res_pct > 0

    def _alquiler_ano_res(yr):
        if not _es_plurianual_res or yr < inicio_ajuste_res:
            return alquiler_mes
        return alquiler_mes * (1 + ajuste_anual_res_pct) ** (yr - inicio_ajuste_res + 1)

    def _renta_neta_ano_res(yr):
        return max(_alquiler_ano_res(yr) - gastos_mes, 0) * 12

    alquiler_ano3 = round(_alquiler_ano_res(3))
    alquiler_ano5 = round(_alquiler_ano_res(5))
    yield_neto_ano3_res = (_renta_neta_ano_res(3) / precio * 100) if precio > 0 else 0
    yield_neto_ano5_res = (_renta_neta_ano_res(5) / precio * 100) if precio > 0 else 0

    payback_indexado_res = None
    if _es_plurianual_res and renta_neta_mes > 0:
        _acum = 0.0
        for _y in range(1, 51):
            _acum += _renta_neta_ano_res(_y)
            if _acum >= precio:
                payback_indexado_res = _y
                break

    tasa_apreciacion = max(inp.get("variacion_anual_pct", 4.0), 0.0) / 100
    tasa_apreciacion = tasa_apreciacion if tasa_apreciacion > 0 else 0.04
    valor_5 = precio * ((1 + tasa_apreciacion)**5)
    valor_10 = precio * ((1 + tasa_apreciacion)**10)
    ganancia_capital_5 = valor_5 - precio
    ganancia_capital_10 = valor_10 - precio

    amort_tabla = []
    if cuota_mensual > 0 and monto_credito > 0:
        saldo = monto_credito
        r = tasa_anual / 12
        for yr in range(1, min(plazo_anos + 1, 11)):
            interes_yr = 0
            capital_yr = 0
            for _ in range(12):
                i = saldo * r
                k = cuota_mensual - i
                interes_yr += i
                capital_yr += k
                saldo = max(saldo - k, 0)
            amort_tabla.append({"año": yr, "capital": capital_yr, "interes": interes_yr, "saldo": saldo})

    return {
        "precio": precio, "pie": pie, "pct_pie": pct_pie * 100,
        "monto_credito": monto_credito, "cuota_mensual": cuota_mensual,
        "total_pagado": total_pagado, "total_intereses": total_intereses,
        "ingreso_minimo": ingreso_minimo, "plazo_anos": plazo_anos,
        "tasa_anual": tasa_anual * 100, "n_meses": n_meses,
        "alquiler_mes": alquiler_mes, "gastos_mes": gastos_mes,
        "renta_neta_mes": renta_neta_mes, "yield_bruto": yield_bruto,
        "yield_neto": yield_neto, "payback_anos": payback_anos,
        "flujo_mensual": flujo_mensual, "alquiler_equilibrio": alquiler_equilibrio,
        "valor_5": valor_5, "valor_10": valor_10,
        "ganancia_capital_5": ganancia_capital_5, "ganancia_capital_10": ganancia_capital_10,
        "amort_tabla": amort_tabla, "uso": uso,
        "tasa_apreciacion_pct": round(tasa_apreciacion * 100, 1),
        # Market / zone fields (populated by caller)
        "zona": inp.get("zona", ""),
        "dormitorios": inp.get("dormitorios", ""),
        "m2": inp.get("m2", 0),
        "antiguedad": inp.get("antiguedad", 0),
        "precio_m2": inp.get("precio_m2", 0),
        "precio_m2_mercado": inp.get("precio_m2_mercado", 0),
        "yield_mercado_pct": inp.get("yield_mercado_pct", 0),
        "alquiler_mercado_m2": inp.get("alquiler_mercado_m2", 0),
        "variacion_anual_pct": inp.get("variacion_anual_pct", 0),
        # Indexación contractual
        "tipo_contrato": tipo_contrato_res,
        "ajuste_anual_pct": round(ajuste_anual_res_pct * 100, 2),
        "inicio_ajuste_ano": inicio_ajuste_res,
        "alquiler_ano3": alquiler_ano3,
        "alquiler_ano5": alquiler_ano5,
        "yield_neto_ano3": round(yield_neto_ano3_res, 1),
        "yield_neto_ano5": round(yield_neto_ano5_res, 1),
        "payback_indexado": payback_indexado_res,
    }


# ═══════════════════════════════════════════════════════
# CALCULADORA INVERSA DE TERRENO
# ═══════════════════════════════════════════════════════

def calcular_terreno_maximo(inp: dict) -> dict:
    zona          = inp.get("zona", "")
    m             = MERCADO.get(zona, {})
    area_terreno  = inp.get("area_terreno", 0)
    area_vendible = inp.get("area_vendible", 0)
    area_techada  = inp.get("area_techada", 0)
    num_pisos     = max(inp.get("num_pisos", 7), 1)
    n_estac       = inp.get("n_estac", 0)
    n_depositos   = inp.get("n_depositos", 0)
    precio_m2     = inp.get("precio_m2", m.get("precio_2br", 0))
    costo_const   = inp.get("costo_construccion", 700)
    costo_sotano  = inp.get("costo_sotano", 450)
    fee_constr    = inp.get("fee_constructora", 10.0) / 100
    tasa_financ   = inp.get("tasa_financ", 9.0)
    tasa_ir       = inp.get("tasa_ir", 29.5) / 100

    ing_dptos    = area_vendible * precio_m2
    ing_estac    = n_estac * m.get("precio_estac", 0)
    ing_deposito = n_depositos * m.get("precio_deposito", 0)
    ing_brutos   = ing_dptos + ing_estac + ing_deposito

    c_obra_dptos   = area_techada * costo_const
    c_obra_sotanos = n_estac * 25 * costo_sotano   # 25 m² área techada por cochera (validado: Clemente X 335)
    c_construccion = (c_obra_dptos + c_obra_sotanos) * (1 + fee_constr)
    c_arq          = area_techada * inp.get("costo_arq_m2", 5.94)
    c_esp          = area_techada * inp.get("costo_esp_m2", 7.92)
    c_factib       = inp.get("costo_factibilidades", 17000)
    c_supervision  = c_construccion * 0.005
    c_permisos         = c_construccion * 0.015
    c_gerencia         = c_construccion * 0.05
    c_ventas_marketing = ing_brutos * 0.05
    c_due_dilig        = 10000
    _meses_obra    = 24 if num_pisos > 20 else (12 if num_pisos <= 5 else 16)
    c_financiero   = c_construccion * 0.75 * tasa_financ / 100 * (_meses_obra / 12)

    c_base_constr  = c_construccion + c_arq + c_esp + c_factib
    c_legales_base = (c_due_dilig + c_base_constr) * 0.005
    # factor de transacción: alcabala 3% + notarial 0.3% + registral 0.15%
    factor_trans   = 1 + 0.03 + 0.003 + 0.0015  # 1.0345
    # c_legales también sube 0.5% del terreno: factor_trans * 0.005 extra por cada $ de terreno
    factor_terreno = factor_trans * 1.005

    # NOTA: c_factib ya está incluido en c_base_constr (línea anterior) — NO sumar de nuevo
    C_fixed = (c_base_constr + c_supervision + c_legales_base + c_permisos
               + c_gerencia + c_ventas_marketing
               + c_due_dilig + c_financiero)

    k = max(1 - tasa_ir, 0.01)

    resultados = {}
    for mg in [0.10, 0.12, 0.15, 0.18, 0.20]:
        target_c_total = ing_brutos * (1 - mg / k)
        T = (target_c_total - C_fixed) / factor_terreno
        resultados[mg] = max(0, round(T))

    tc = float((st.secrets.get("mercado") or {}).get("tipo_cambio", 3.45))

    return {
        "ing_brutos":    round(ing_brutos),
        "C_fixed":       round(C_fixed),
        "c_construccion": round(c_construccion),
        "c_financiero":  round(c_financiero),
        "area_terreno":  area_terreno,
        "area_vendible": area_vendible,
        "area_techada":  area_techada,
        "precio_m2":     precio_m2,
        "zona":          zona,
        "resultados":    resultados,
        "tipo_cambio":   tc,
    }


