# ═══════════════════════════════════════════════════════
# GEOMETRÍA DE LOTE
# ═══════════════════════════════════════════════════════

def _geo_poligono_tabular(frente: float, fondo: float, lado_izq: float, lado_der: float) -> "ShapelyPolygon | None":
    """
    Construye polígono shapely desde 4 medidas perimetrales.
    Modelo: trapezoide con frente en base y fondo en tope.
    Si los 4 lados son iguales → rectángulo exacto.
    """
    if not _SHAPELY_OK:
        return None
    if frente <= 0 or fondo <= 0 or lado_izq <= 0 or lado_der <= 0:
        return None
    # Altura del trapecio desde lado izquierdo
    offset = (frente - fondo) / 2.0
    h_izq = math.sqrt(max(0, lado_izq**2 - offset**2))
    h_der = math.sqrt(max(0, lado_der**2 - offset**2))
    h = (h_izq + h_der) / 2.0
    if h <= 0:
        return None
    # Vértices: base inferior izq → der, base superior der → izq
    coords = [
        (0.0,      0.0),
        (frente,   0.0),
        (frente - offset, h),
        (offset,   h),
    ]
    poly = ShapelyPolygon(coords)
    return make_valid(poly) if not poly.is_valid else poly


def _geo_poligono_dxf(fileobj) -> "ShapelyPolygon | None":
    """
    Extrae el polígono perimetral más grande de un archivo DXF/DWG.
    Busca LWPOLYLINE o POLYLINE cerradas; devuelve la de mayor área.
    """
    if not _SHAPELY_OK or not _EZDXF_OK:
        return None
    try:
        doc = ezdxf.read(fileobj)
        msp = doc.modelspace()
        best, best_area = None, 0.0
        for ent in msp:
            pts = None
            if ent.dxftype() == "LWPOLYLINE":
                pts = [(p[0], p[1]) for p in ent.get_points()]
            elif ent.dxftype() == "POLYLINE":
                try:
                    pts = [(v.dxf.location.x, v.dxf.location.y) for v in ent.vertices]
                except Exception:
                    continue
            if pts and len(pts) >= 3:
                try:
                    poly = ShapelyPolygon(pts)
                    if not poly.is_valid:
                        poly = make_valid(poly)
                    if poly.area > best_area:
                        best_area, best = poly.area, poly
                except Exception:
                    continue
        return best
    except Exception:
        return None


def _geo_aplicar_retiros(poly: "ShapelyPolygon", ret_frontal: float, ret_lat: float, ret_posterior: float) -> "ShapelyPolygon | None":
    """
    Aplica retiros direccionales al polígono del lote.
    Coordenadas de _geo_poligono_tabular: y=0 es el frente (calle), y=h es el posterior.
    Solo recorta las caras que tienen retiro > 0 — práctica Lima: ret_lat=0, ret_post=0.
    """
    if not _SHAPELY_OK or poly is None:
        return None
    from shapely.geometry import box as _box_geo
    x0, y0, x1, y1 = poly.bounds
    clip = _box_geo(
        x0 + ret_lat,
        y0 + ret_frontal,
        x1 - ret_lat,
        y1 - (ret_posterior if ret_posterior > 0 else 0),
    )
    huella = poly.intersection(clip)
    if huella.is_empty or not huella.is_valid:
        return None
    return huella


def _geo_validar(poly_lote, poly_huella, n_pisos: int, frente: float,
                 uso: str = "residencial", area_libre_min_pct: float = 0.0) -> dict:
    """
    Valida la geometría contra RNE y devuelve alertas + métricas.
    area_libre_min_pct: porcentaje de área libre mínima exigida por el CPU (ej. 40.0).
    """
    result = {"ok": True, "alertas": [], "metricas": {}}
    if poly_lote is None:
        result["ok"] = False
        result["alertas"].append("Sin geometría de lote definida.")
        return result

    area_lote   = poly_lote.area
    area_huella = poly_huella.area if poly_huella and not poly_huella.is_empty else 0.0
    cos_real    = round(area_huella / area_lote * 100, 1) if area_lote > 0 else 0.0

    # Restricción normativa de área libre: COS máximo = 100 − área_libre_min_pct
    cos_max_norma = 100.0 - area_libre_min_pct if area_libre_min_pct > 0 else 100.0
    area_huella_efectiva = min(area_huella, area_lote * cos_max_norma / 100)
    at_sobre = area_huella_efectiva * n_pisos

    # Frente mínimo
    frente_min = 13.0 if uso == "residencial" else 20.0
    if frente < frente_min:
        result["alertas"].append(f"Frente {frente:.1f}m < mínimo {frente_min:.0f}m para uso {uso}.")
        result["ok"] = False

    # Área de huella vs lote
    if area_huella <= 0:
        result["alertas"].append("Los retiros consumen todo el lote — revisar parámetros.")
        result["ok"] = False

    # Alerta si COS real supera el límite normativo
    if area_libre_min_pct > 0 and cos_real > cos_max_norma:
        result["alertas"].append(
            f"COS real ({cos_real:.1f}%) supera el máximo normativo ({cos_max_norma:.0f}%) "
            f"por área libre mínima exigida ({area_libre_min_pct:.0f}%). "
            f"Área techada efectiva limitada a {area_huella_efectiva:,.0f} m²."
        )

    # Pozos de luz RNE A.020: para >6 pisos exige pozo mínimo
    if n_pisos > 6 and uso == "residencial":
        h_edif = n_pisos * 3.0
        pozo_min = round(h_edif * 0.15, 1)
        result["alertas"].append(
            f"RNE A.020: edificio de {n_pisos} pisos ({h_edif:.0f}m) requiere pozos de luz ≥{pozo_min}m — verificar en planta.")

    result["metricas"] = {
        "area_lote_m2":          round(area_lote, 1),
        "area_huella_m2":        round(area_huella, 1),
        "area_huella_efectiva_m2": round(area_huella_efectiva, 1),
        "cos_real_pct":          cos_real,
        "cos_max_norma_pct":     cos_max_norma,
        "at_sobre_m2":           round(at_sobre, 0),
    }
    return result


def _geo_render_3d(poly_lote, poly_huella, n_pisos: int, n_sotanos: int = 0,
                   h_piso: float = 3.0, h_sotano: float = 2.6) -> go.Figure:
    """Genera visualización 3D del massing con Plotly."""
    GOLD, BLUE, RED = "#C9A96E", "#4A90C4", "#C44A4A"

    def _ring_trace(poly, z_val, color, name="", width=2, showlegend=False):
        if poly is None or poly.is_empty:
            return None
        xs, ys = poly.exterior.xy
        return go.Scatter3d(
            x=list(xs), y=list(ys), z=[z_val] * len(xs),
            mode="lines", line=dict(color=color, width=width),
            name=name, showlegend=showlegend
        )

    traces = []

    # Límite del lote
    t = _ring_trace(poly_lote, 0, GOLD, "Lote", width=3, showlegend=True)
    if t:
        traces.append(t)

    if poly_huella and not poly_huella.is_empty:
        hxs, hys = list(poly_huella.exterior.xy[0]), list(poly_huella.exterior.xy[1])
        total_h = n_pisos * h_piso
        sotano_d = n_sotanos * h_sotano

        # Líneas de piso sobre rasante
        for p in range(n_pisos + 1):
            z = p * h_piso
            lbl = "Huella edificable" if p == 0 else ""
            show = p == 0
            t = _ring_trace(poly_huella, z, BLUE, lbl, width=2 if p == 0 else 1, showlegend=show)
            if t:
                traces.append(t)

        # Aristas verticales
        for cx, cy in zip(hxs[:-1], hys[:-1]):
            traces.append(go.Scatter3d(
                x=[cx, cx], y=[cy, cy], z=[-sotano_d, total_h],
                mode="lines", line=dict(color=BLUE, width=1), showlegend=False
            ))

        # Líneas de sótano
        for s in range(1, n_sotanos + 1):
            z = -s * h_sotano
            lbl = "Sótanos" if s == 1 else ""
            t = _ring_trace(poly_huella, z, GOLD, lbl, width=1, showlegend=(s == 1))
            if t:
                traces.append(t)

    fig = go.Figure(data=traces)
    fig.update_layout(
        scene=dict(
            xaxis=dict(title="m", showgrid=True, gridcolor="rgba(255,255,255,0.08)"),
            yaxis=dict(title="m", showgrid=True, gridcolor="rgba(255,255,255,0.08)"),
            zaxis=dict(title="altura (m)", showgrid=True, gridcolor="rgba(255,255,255,0.08)"),
            bgcolor="#0E1E2E", aspectmode="data",
            camera=dict(eye=dict(x=1.6, y=-1.6, z=1.2)),
        ),
        paper_bgcolor="#0A1628",
        font=dict(color="white", size=10),
        margin=dict(l=0, r=0, t=10, b=0),
        height=420,
        legend=dict(x=0.02, y=0.97, bgcolor="rgba(10,22,40,0.8)",
                    bordercolor="rgba(71,85,105,0.3)", font=dict(size=10)),
    )
    return fig


def _geo_render_3d_industrial(poly_lote, poly_nave, h_nave: float) -> go.Figure:
    """Massing 3D industrial — tema claro, nave sólida + patio + docks + circulación."""
    GOLD  = "#C9A96E"
    NAVY  = "#1A3A5C"
    SAND  = "#C8A86E"
    RED   = "#C44A4A"
    GREEN = "#2E8B57"
    BG    = "#F8F5F0"

    traces = []

    if poly_lote and not poly_lote.is_empty:
        lxs, lys = poly_lote.exterior.xy
        traces.append(go.Scatter3d(
            x=list(lxs), y=list(lys), z=[0.0] * len(lxs),
            mode="lines", line=dict(color=GOLD, width=4),
            name="Límite del lote", showlegend=True,
        ))

    if poly_nave and not poly_nave.is_empty:
        nxs_r, nys_r = poly_nave.exterior.xy
        nxs = list(nxs_r[:-1])
        nys = list(nys_r[:-1])
        n = len(nxs)
        vx = nxs + nxs
        vy = nys + nys
        vz = [0.0] * n + [float(h_nave)] * n
        ii, jj, kk = [], [], []
        for t in range(1, n - 1):
            ii += [0];    jj += [t + 1]; kk += [t]
        for t in range(1, n - 1):
            ii += [n];    jj += [n + t]; kk += [n + t + 1]
        for t in range(n):
            nt = (t + 1) % n
            ii += [t, nt]; jj += [nt, n + nt]; kk += [n + t, n + t]
        traces.append(go.Mesh3d(
            x=vx, y=vy, z=vz, i=ii, j=jj, k=kk,
            color=NAVY, opacity=0.72, name="Nave industrial", showlegend=True,
            flatshading=False,
            lighting=dict(ambient=0.6, diffuse=0.8, specular=0.2, roughness=0.7),
        ))
        for lvl in [0.0, float(h_nave)]:
            traces.append(go.Scatter3d(
                x=list(nxs_r), y=list(nys_r), z=[lvl] * len(nxs_r),
                mode="lines", line=dict(color=NAVY, width=2), showlegend=False,
            ))
        for cx, cy in zip(nxs, nys):
            traces.append(go.Scatter3d(
                x=[cx, cx], y=[cy, cy], z=[0.0, float(h_nave)],
                mode="lines", line=dict(color=NAVY, width=1), showlegend=False,
            ))
        try:
            minx_n, miny_n, maxx_n, maxy_n = poly_nave.bounds
            frente_n = maxx_n - minx_n
            n_docks = max(2, min(6, int(frente_n / 9)))
            dock_spacing = frente_n / (n_docks + 1)
            for d in range(n_docks):
                dx = minx_n + dock_spacing * (d + 1)
                traces.append(go.Scatter3d(
                    x=[dx, dx], y=[miny_n, miny_n], z=[0.0, 1.8],
                    mode="lines", line=dict(color=RED, width=8),
                    name="Dock de carga" if d == 0 else "",
                    showlegend=(d == 0),
                ))
            hx = minx_n - 3
            hy = (miny_n + maxy_n) / 2
            traces.append(go.Scatter3d(
                x=[hx, hx, hx], y=[hy, hy, hy], z=[0.0, h_nave / 2, float(h_nave)],
                mode="lines+text",
                line=dict(color="#555555", width=2, dash="dot"),
                text=["", f"{h_nave:.1f}m", ""],
                textfont=dict(size=11, color="#333333"),
                name="Altura nave", showlegend=False,
            ))
        except Exception:
            pass

    if poly_lote and poly_nave and not poly_lote.is_empty and not poly_nave.is_empty:
        try:
            from shapely.geometry import MultiPolygon as _MP
            poly_patio = poly_lote.difference(poly_nave)
            if not poly_patio.is_empty:
                if isinstance(poly_patio, _MP):
                    poly_patio = max(poly_patio.geoms, key=lambda g: g.area)
                pxs_r, pys_r = poly_patio.exterior.xy
                pxs = list(pxs_r[:-1])
                pys = list(pys_r[:-1])
                np_ = len(pxs)
                if np_ >= 3:
                    pi, pj, pk = [], [], []
                    for t in range(1, np_ - 1):
                        pi += [0]; pj += [t]; pk += [t + 1]
                    traces.append(go.Mesh3d(
                        x=pxs, y=pys, z=[0.02] * np_,
                        i=pi, j=pj, k=pk,
                        color=SAND, opacity=0.55,
                        name="Patio / Maniobras", showlegend=True,
                    ))
        except Exception:
            pass
        try:
            minx_l, miny_l, maxx_l, _ = poly_lote.bounds
            minx_n2, miny_n2, maxx_n2, _ = poly_nave.bounds
            mid_x = (minx_l + maxx_l) / 2
            gap = max(miny_n2 - miny_l, 6)
            traces.append(go.Cone(
                x=[mid_x - 8, mid_x + 8],
                y=[miny_l + gap * 0.30, miny_l + gap * 0.70],
                z=[1.2, 1.2],
                u=[0, 0], v=[1, 1], w=[0, 0],
                sizemode="absolute", sizeref=5,
                colorscale=[[0, GREEN], [1, GREEN]],
                showscale=False, name="Circulación", showlegend=True, anchor="tip",
            ))
        except Exception:
            pass

    lim_z = max(float(h_nave) * 1.25, 8.0)
    fig = go.Figure(data=traces)
    fig.update_layout(
        scene=dict(
            xaxis=dict(title="m", showgrid=True, gridcolor="rgba(30,58,92,0.15)",
                       backgroundcolor=BG, showbackground=True),
            yaxis=dict(title="m", showgrid=True, gridcolor="rgba(30,58,92,0.15)",
                       backgroundcolor=BG, showbackground=True),
            zaxis=dict(title="altura (m)", showgrid=True, gridcolor="rgba(30,58,92,0.15)",
                       backgroundcolor=BG, showbackground=True, range=[0, lim_z]),
            bgcolor=BG, aspectmode="data",
            camera=dict(eye=dict(x=1.8, y=-1.8, z=1.4)),
        ),
        paper_bgcolor=BG,
        font=dict(color=NAVY, size=10),
        margin=dict(l=0, r=0, t=10, b=0),
        height=420,
        legend=dict(x=0.02, y=0.97, bgcolor="rgba(248,245,240,0.92)",
                    bordercolor=GOLD, borderwidth=1, font=dict(size=9, color=NAVY)),
    )
    return fig


def _geo_render_planta_industrial(poly_lote, poly_nave, h_nave: float) -> go.Figure:
    """Vista en planta industrial — estilo plano arquitectónico (fondo papel, hachura, racks, docks)."""
    NEGRO    = "#1A1A2E"
    NAVY     = "#1A3A5C"
    PAPER    = "#F5F3EE"    # fondo papel técnico
    PATIO_BG = "#EAE6DC"    # patio de maniobras
    NAVE_BG  = "#D6E8F5"    # relleno nave
    DOCK_COL = "#4A7FAA"    # docks de carga
    RACK_COL = "rgba(26,58,92,0.18)"   # filas de racks sugeridas
    FONT_DRF = "Courier New, monospace"  # fuente tipo drafting

    area_lote  = poly_lote.area if (poly_lote and not poly_lote.is_empty) else 0.0
    area_nave  = poly_nave.area if (poly_nave and not poly_nave.is_empty) else 0.0
    area_patio = max(0.0, area_lote - area_nave)
    pct_nave   = (area_nave  / area_lote * 100) if area_lote > 0 else 0.0
    pct_patio  = (area_patio / area_lote * 100) if area_lote > 0 else 0.0

    traces: list      = []
    annotations: list = []
    shapes: list      = []

    # ── 1. Lote — borde grueso, patio con hachura punteada ────
    if poly_lote and not poly_lote.is_empty:
        lxs, lys = poly_lote.exterior.xy
        traces.append(go.Scatter(
            x=list(lxs), y=list(lys),
            fill="toself", fillcolor=PATIO_BG,
            line=dict(color=NEGRO, width=3),
            mode="lines", showlegend=False,
            fillpattern=dict(shape=".", bgcolor=PATIO_BG,
                             fgcolor="rgba(100,85,55,0.30)", size=5, solidity=0.5),
        ))

    # ── 2. Nave — hachura diagonal azul (convención plano) ────
    if poly_nave and not poly_nave.is_empty:
        nxs, nys = poly_nave.exterior.xy
        traces.append(go.Scatter(
            x=list(nxs), y=list(nys),
            fill="toself", fillcolor=NAVE_BG,
            line=dict(color=NAVY, width=2),
            mode="lines", showlegend=False,
            fillpattern=dict(shape="/", bgcolor=NAVE_BG,
                             fgcolor="rgba(26,58,92,0.50)", size=9, solidity=0.55),
        ))

        try:
            minx_n, miny_n, maxx_n, maxy_n = poly_nave.bounds
            nave_w = maxx_n - minx_n
            nave_d = maxy_n - miny_n

            # ── Racks sugeridos: franjas horizontales alternadas ──
            rack_h   = max(2.0, nave_d / 18)   # alto visual de cada rack
            aisle_h  = rack_h * 0.55
            step     = rack_h + aisle_h
            rack_margin = nave_w * 0.06
            y_cur = miny_n + nave_d * 0.04
            while y_cur + rack_h < maxy_n - nave_d * 0.04:
                shapes.append(dict(
                    type="rect",
                    x0=minx_n + rack_margin, y0=y_cur,
                    x1=maxx_n - rack_margin, y1=y_cur + rack_h,
                    xref="x", yref="y",
                    line=dict(color="rgba(26,58,92,0.55)", width=0.8),
                    fillcolor=RACK_COL,
                ))
                y_cur += step

            # ── Docks de carga — frente de la nave ──────────────
            n_docks = max(2, min(6, int(nave_w / 10)))
            dock_w  = min(3.5, nave_w / (n_docks + 1) * 0.7)
            dock_d  = max(2.0, nave_d * 0.03)
            spacing = nave_w / (n_docks + 1)
            for d in range(n_docks):
                dx0 = minx_n + spacing * (d + 1) - dock_w / 2
                shapes.append(dict(
                    type="rect",
                    x0=dx0, y0=miny_n - dock_d,
                    x1=dx0 + dock_w, y1=miny_n,
                    xref="x", yref="y",
                    line=dict(color=DOCK_COL, width=1.5),
                    fillcolor="#8BB8D8",
                ))

            # ── Pasillo central (línea de circulación peatonal) ──
            cx = (minx_n + maxx_n) / 2
            shapes.append(dict(
                type="line",
                x0=cx, y0=miny_n + nave_d * 0.03,
                x1=cx, y1=maxy_n - nave_d * 0.03,
                xref="x", yref="y",
                line=dict(color=NAVY, width=1, dash="dash"),
            ))

        except Exception:
            pass

        # ── Label nave ───────────────────────────────────────────
        annotations.append(dict(
            x=poly_nave.centroid.x,
            y=poly_nave.centroid.y,
            text=(f"<b>NAVE INDUSTRIAL</b><br>"
                  f"{area_nave:,.0f} m²  ·  {pct_nave:.0f}% del lote<br>"
                  f"Alt. hombro: {h_nave:.1f} m"),
            showarrow=False,
            font=dict(size=11, color=NAVY, family=FONT_DRF),
            align="center",
            bgcolor="rgba(255,255,255,0.86)",
            bordercolor=NAVY,
            borderwidth=1,
            borderpad=5,
        ))

    # ── 3. Patio — label centrado en la franja frontal ────────
    if poly_lote and poly_nave and not poly_lote.is_empty and not poly_nave.is_empty:
        try:
            _bxl = poly_lote.bounds
            _bxn = poly_nave.bounds
            # Centroide del patio frontal (entre borde lote y frente de nave)
            _pat_cx = (_bxl[0] + _bxl[2]) / 2
            _pat_cy = (_bxl[1] + _bxn[1]) / 2
            annotations.append(dict(
                x=_pat_cx, y=_pat_cy,
                text=(f"<b>PATIO DE MANIOBRAS</b><br>"
                      f"{area_patio:,.0f} m²  ·  {pct_patio:.0f}%<br>"
                      f"<i>Radio giro tráileres</i>"),
                showarrow=False,
                font=dict(size=10, color="#4A3A18", family=FONT_DRF),
                align="center",
                bgcolor="rgba(255,255,255,0.82)",
                bordercolor="#8A7A4A",
                borderwidth=1,
                borderpad=4,
            ))
        except Exception:
            pass

    # ── 4. Símbolo Norte — interior esquina sup-derecha del lote ─
    if poly_lote and not poly_lote.is_empty:
        _bx  = poly_lote.bounds
        _w   = _bx[2] - _bx[0]
        _h   = _bx[3] - _bx[1]
        # Posición: dentro del lote, esquina superior derecha
        _nx   = _bx[2] - _w * 0.05   # 5% desde el borde derecho
        _ny_t = _bx[3] - _h * 0.02   # punta de la flecha (casi en el borde top)
        _ny_b = _bx[3] - _h * 0.09   # cola de la flecha
        annotations.append(dict(
            x=_nx, y=_ny_t,
            ax=_nx, ay=_ny_b,
            xref="x", yref="y", axref="x", ayref="y",
            text="<b>N</b>", showarrow=True,
            arrowhead=2, arrowsize=1.6, arrowwidth=2.2,
            arrowcolor=NEGRO,
            font=dict(size=10, color=NEGRO, family=FONT_DRF),
            xanchor="center", yanchor="top",
            bgcolor="rgba(255,255,255,0.85)",
            bordercolor=NEGRO,
            borderwidth=1,
            borderpad=2,
        ))
        # ── Leyenda — esquina inferior izquierda del lote ────────
        annotations.append(dict(
            x=_bx[0] + _w * 0.02, y=_bx[1] + _h * 0.02,
            text="■ Dock de carga  ── Pasillo central",
            showarrow=False,
            font=dict(size=8, color="#555555", family=FONT_DRF),
            xanchor="left", yanchor="bottom",
            bgcolor="rgba(255,255,255,0.80)",
            bordercolor="#AAAAAA",
            borderwidth=1,
            borderpad=3,
        ))

    # ── 5. Layout — rangos ceñidos al lote, sin scaleanchor ───
    _dtick = 10.0
    _xrange, _yrange = None, None
    _fig_height = 420
    if poly_lote and not poly_lote.is_empty:
        _bx2 = poly_lote.bounds
        _lw  = _bx2[2] - _bx2[0]   # ancho del lote
        _lh  = _bx2[3] - _bx2[1]   # fondo del lote
        _span = max(_lw, _lh)
        _dtick = 25.0 if _span > 250 else (20.0 if _span > 150 else 10.0)
        # Rangos ajustados al lote + margen mínimo para flecha N y leyenda
        _xrange = [_bx2[0] - _lw * 0.06, _bx2[2] + _lw * 0.18]
        _yrange = [_bx2[1] - _lh * 0.06, _bx2[3] + _lh * 0.06]
        # Altura proporcional al aspecto del lote (capped entre 300 y 460)
        _aspect = (_lh / _lw) if _lw > 0 else 1.0
        _fig_height = max(300, min(460, int(370 * _aspect)))

    fig = go.Figure(data=traces)
    _ax_common = dict(
        showgrid=True, gridcolor="rgba(150,150,130,0.30)", gridwidth=1,
        dtick=_dtick, zeroline=False, showticklabels=True,
        tickfont=dict(size=8, color="#888880", family=FONT_DRF),
        ticksuffix="m", showline=True, linecolor="#AAAAAA",
        ticks="outside", ticklen=4,
    )
    # scaleanchor + constrain="domain": mantiene 1:1 proporción
    # encogiendo el dominio X en lugar de expandir el rango
    _x_ax = dict(scaleanchor="y", scaleratio=1, constrain="domain", **_ax_common)
    _y_ax = dict(**_ax_common)
    if _xrange:
        _x_ax["range"] = _xrange
    if _yrange:
        _y_ax["range"] = _yrange

    fig.update_layout(
        shapes=shapes,
        xaxis=_x_ax,
        yaxis=_y_ax,
        paper_bgcolor=PAPER,
        plot_bgcolor=PAPER,
        margin=dict(l=42, r=12, t=14, b=42),
        height=_fig_height,
        annotations=annotations,
    )
    return fig


def _gen_seccion_alturas(n_pisos: int, n_sotanos: int = 0,
                         h_piso: float = 2.65, h_sotano: float = 2.80) -> go.Figure:
    """Esquema de alturas 2D — sección arquitectónica."""
    NAVY = "#1E2D3D"
    GOLD = "#C9A96E"
    RED  = "#C44A4A"
    GREY = "#9A9590"
    BG   = "#FFFFFF"

    az_h  = 1.5
    BX0, BX1 = 1.5, 3.5
    DIM_X = BX1 + 0.40

    z_bot = -(n_sotanos * h_sotano)
    z_top = n_pisos * h_piso + az_h

    shapes = []
    annotations = []

    # Cuerpo sobre rasante
    shapes.append(dict(type="rect", x0=BX0, x1=BX1, y0=0, y1=n_pisos * h_piso,
                       line=dict(color=NAVY, width=2),
                       fillcolor="rgba(30,45,61,0.05)"))
    # Azotea (recuadro más estrecho)
    shapes.append(dict(type="rect", x0=BX0 + 0.22, x1=BX1 - 0.22,
                       y0=n_pisos * h_piso, y1=z_top,
                       line=dict(color=NAVY, width=2),
                       fillcolor="rgba(30,45,61,0.10)"))
    # Sótanos
    if n_sotanos > 0:
        shapes.append(dict(type="rect", x0=BX0, x1=BX1, y0=z_bot, y1=0,
                           line=dict(color=NAVY, width=2),
                           fillcolor="rgba(30,45,61,0.12)"))
        # Línea de terreno
        shapes.append(dict(type="line", x0=0.3, x1=5.2, y0=0, y1=0,
                           line=dict(color=GOLD, width=2.5)))
        annotations.append(dict(x=0.25, y=0, text="<b>N.0.00</b>",
                                 xanchor="right", yanchor="middle", showarrow=False,
                                 font=dict(size=9, color=GOLD, family="Courier New, monospace")))
    else:
        shapes.append(dict(type="line", x0=0.3, x1=5.2, y0=0, y1=0,
                           line=dict(color=GOLD, width=1.5, dash="dot")))
        annotations.append(dict(x=0.25, y=0, text="N.0.00",
                                 xanchor="right", yanchor="middle", showarrow=False,
                                 font=dict(size=9, color=GOLD, family="Courier New, monospace")))

    # Líneas de piso sobre rasante
    for p in range(1, n_pisos):
        shapes.append(dict(type="line", x0=BX0, x1=BX1, y0=p * h_piso, y1=p * h_piso,
                           line=dict(color=NAVY, width=0.7)))
    # Líneas de sótano
    for s in range(1, n_sotanos):
        shapes.append(dict(type="line", x0=BX0, x1=BX1,
                           y0=-s * h_sotano, y1=-s * h_sotano,
                           line=dict(color=NAVY, width=0.7, dash="dot")))
    # Rampa entre sótanos
    if n_sotanos >= 2:
        rx = BX0 + (BX1 - BX0) * 0.28
        for s in range(1, n_sotanos):
            ya = -(s - 1) * h_sotano - 0.25 if s > 1 else -0.25
            yb = -s * h_sotano + 0.25
            shapes.append(dict(type="line", x0=rx, x1=rx + 0.35, y0=ya, y1=yb,
                               line=dict(color=GREY, width=1, dash="dot")))

    # Etiquetas izquierda (nombre de nivel)
    for p in range(1, n_pisos + 1):
        annotations.append(dict(
            x=BX0 - 0.08, y=p * h_piso, text=f"P{p:02d}",
            xanchor="right", yanchor="middle", showarrow=False,
            font=dict(size=9, color=NAVY, family="Courier New, monospace")))
    annotations.append(dict(
        x=BX0 - 0.08, y=z_top, text="AZ",
        xanchor="right", yanchor="middle", showarrow=False,
        font=dict(size=9, color=NAVY, family="Courier New, monospace")))
    for s in range(1, n_sotanos + 1):
        annotations.append(dict(
            x=BX0 - 0.08, y=-s * h_sotano, text=f"S{s}",
            xanchor="right", yanchor="middle", showarrow=False,
            font=dict(size=9, color=NAVY, family="Courier New, monospace")))

    # Etiquetas derecha (cota)
    for p in range(1, n_pisos + 1):
        annotations.append(dict(
            x=BX1 + 0.08, y=p * h_piso, text=f"+{p * h_piso:.2f}",
            xanchor="left", yanchor="middle", showarrow=False,
            font=dict(size=9, color=GREY, family="Courier New, monospace")))
    annotations.append(dict(
        x=BX1 + 0.08, y=z_top, text=f"+{z_top:.2f}",
        xanchor="left", yanchor="middle", showarrow=False,
        font=dict(size=9, color=GREY, family="Courier New, monospace")))
    annotations.append(dict(
        x=BX1 + 0.08, y=0, text="±0.00",
        xanchor="left", yanchor="middle", showarrow=False,
        font=dict(size=9, color=GOLD, family="Courier New, monospace")))
    for s in range(1, n_sotanos + 1):
        annotations.append(dict(
            x=BX1 + 0.08, y=-s * h_sotano, text=f"{-s * h_sotano:.2f}",
            xanchor="left", yanchor="middle", showarrow=False,
            font=dict(size=9, color=GREY, family="Courier New, monospace")))

    # Cota de altura de piso (flecha roja entre P01 y P02)
    if n_pisos >= 2:
        for dz in [h_piso, 2 * h_piso]:
            shapes.append(dict(type="line", x0=DIM_X - 0.06, x1=DIM_X + 0.06, y0=dz, y1=dz,
                               line=dict(color=RED, width=1.5)))
        shapes.append(dict(type="line", x0=DIM_X, x1=DIM_X, y0=h_piso, y1=2 * h_piso,
                           line=dict(color=RED, width=1.5)))
        annotations.append(dict(
            x=DIM_X + 0.12, y=1.5 * h_piso, text=f"{h_piso:.2f}m",
            xanchor="left", yanchor="middle", showarrow=False,
            font=dict(size=9, color=RED, family="Courier New, monospace")))

    # Título y metadatos
    h_total = n_pisos * h_piso
    meta = f"CPU {n_pisos} PISOS: {h_total:.2f}ml  ·  ALT. PISO A PISO: {h_piso:.2f}m"
    if n_sotanos > 0:
        meta += f"  ·  {n_sotanos} SÓTANO{'S' if n_sotanos > 1 else ''}"
    annotations.append(dict(
        x=BX0, y=z_top + 0.85, text="<b>ESQUEMA DE ALTURAS</b>",
        xanchor="left", yanchor="bottom", showarrow=False,
        font=dict(size=12, color=NAVY, family="Inter, sans-serif")))
    annotations.append(dict(
        x=BX0, y=z_top + 0.35, text=meta,
        xanchor="left", yanchor="bottom", showarrow=False,
        font=dict(size=9, color=GREY, family="Courier New, monospace")))

    height_px = max(380, min(700, int((z_top - z_bot) * 30) + 130))
    fig = go.Figure()
    fig.add_trace(go.Scatter(x=[None], y=[None], showlegend=False))
    fig.update_layout(
        shapes=shapes, annotations=annotations,
        paper_bgcolor=BG, plot_bgcolor=BG,
        height=height_px,
        margin=dict(l=60, r=90, t=70, b=30),
        xaxis=dict(range=[0, 5.8], showticklabels=False,
                   showgrid=False, zeroline=False, visible=False),
        yaxis=dict(range=[z_bot - 1.2, z_top + 1.8],
                   showticklabels=False, showgrid=False,
                   zeroline=False, visible=False),
    )
    return fig


def _gen_massing_3d_solid(poly_lote, poly_huella, n_pisos: int,
                           n_sotanos: int = 0, h_piso: float = 2.65,
                           h_sotano: float = 2.80,
                           unidades: list = None) -> go.Figure:
    """Massing 3D — celdas individuales por departamento, tipología visible por piso."""
    BGND = "#F0F2F6"
    GOLD = "#C9A96E"
    TEXT = "#1E2D3D"
    GREY = "#5A6A7A"
    GAP  = 0.05

    _TIPO_COLOR = {
        "1D":     "#4AB3D9",   # azul claro — unidades pequeñas
        "2D":     "#2A78C8",   # azul medio — unidades estándar
        "3D":     "#E8833A",   # naranja — unidades premium (diferenciado de azotea)
        "PH":     "#9B59B6",   # púrpura — penthouse
        "DUP":    "#7D3C98",   # púrpura oscuro — dúplex último piso
        "AZ":     "#C8A050",   # dorado — reservado para azotea técnica
        "AZ_HAB": "#E67E22",   # naranja cálido — azotea habitable (con dúplex)
    }
    _TIPO_AREA  = {"1D": 50, "2D": 80, "3D": 120, "PH": 160}   # fallback m² estimado
    _TIPO_SHORT = {
        "1 Dorm.": "1D", "2 Dorm.": "2D", "3 Dorm.": "3D",
        "1D": "1D", "2D": "2D", "3D": "3D",
        "Dúplex": "DUP", "Duplex": "DUP", "PH": "PH",
        "Azotea": "AZ_HAB", "Azotea habitable": "AZ_HAB",
    }

    # ── Construir mapa piso → lista de tipologías (una por unidad) ────────
    def _build_floor_cells(unids, n):
        """Devuelve dict {piso_idx: [("1D", area), ("2D", area), ...]}"""
        if not unids or not n:
            return {}
        # Expandir todas las unidades en una cola ordenada
        orden = ["1 Dorm.", "1D", "2 Dorm.", "2D", "3 Dorm.", "3D", "Dúplex", "PH"]
        cola = []
        for key in orden:
            for u in unids:
                t = u.get("tipo", "")
                if t != key:
                    continue
                short = _TIPO_SHORT.get(t, t[:2])
                area  = float(u.get("area_util") or u.get("area") or _TIPO_AREA.get(short, 80))
                cant  = int(u.get("cantidad", 0))
                for _ in range(cant):
                    cola.append((short, area))
        # Distribuir: 2 unidades por piso típico (o 1 si la cola es muy corta)
        units_per_floor = max(1, round(len(cola) / max(n, 1)))
        units_per_floor = min(units_per_floor, 4)  # máx 4 unidades/piso visibles
        fmap = {}
        idx  = 0
        for p in range(n):
            fmap[p] = []
            for _ in range(units_per_floor):
                if idx < len(cola):
                    fmap[p].append(cola[idx])
                    idx += 1
        return fmap

    _floor_cells = _build_floor_cells(unidades or [], n_pisos)

    def _floor_color_gradient(i, total):
        f = i / max(total - 1, 1)
        r = int(0x12 + (0x4A - 0x12) * f)
        g = int(0x22 + (0x6A - 0x22) * f)
        b = int(0x3A + (0x90 - 0x3A) * f)
        return f"#{r:02X}{g:02X}{b:02X}"

    def _box(x0, y0, x1, y1, z0, z1, color, opacity=1.0, name="",
             show_leg=False, hover="skip", customdata=None):
        vx = [x0, x1, x1, x0, x0, x1, x1, x0]
        vy = [y0, y0, y1, y1, y0, y0, y1, y1]
        vz = [z0+GAP, z0+GAP, z0+GAP, z0+GAP, z1-GAP, z1-GAP, z1-GAP, z1-GAP]
        return go.Mesh3d(
            x=vx, y=vy, z=vz,
            i=[0,0,4,4, 0,1,5,4, 1,2,6,5, 2,3,7,6, 3,0,4,7, 4,5,6,4],
            j=[1,2,5,6, 1,5,5,0, 2,6,6,1, 3,7,7,2, 0,4,7,3, 5,6,7,6],
            k=[2,3,6,7, 5,4,1,4, 6,5,2,5, 7,6,3,6, 4,7,3,4, 6,7,4,7],
            color=color, opacity=opacity,
            flatshading=True,
            lighting=dict(ambient=0.6, diffuse=0.95, specular=0.35, roughness=0.45, fresnel=0.2),
            lightposition=dict(x=100, y=200, z=300),
            name=name, showlegend=show_leg,
            hoverinfo=hover,
            hovertemplate=customdata if customdata else None,
        )

    def _tiene_duplex(unids):
        """True si hay unidades de tipo Dúplex o PH en el proyecto."""
        if not unids:
            return False
        return any(_TIPO_SHORT.get(u.get("tipo", ""), "") in {"DUP", "PH"}
                   for u in unids)

    _hay_duplex = _tiene_duplex(unidades or [])

    traces = []

    # Building bounds
    if poly_huella and not poly_huella.is_empty:
        hx0, hy0, hx1, hy1 = poly_huella.bounds
    else:
        hx0, hy0, hx1, hy1 = 0, 0, 20, 15
    if poly_lote and not poly_lote.is_empty:
        lx0, ly0, lx1, ly1 = poly_lote.bounds
    else:
        lx0, ly0, lx1, ly1 = hx0-2, hy0-2, hx1+2, hy1+2

    bw   = hx1 - hx0
    bd   = hy1 - hy0
    # Label anchor — frente del edificio, desplazado hacia la cámara
    lbl_y = hy0 - max(bd * 0.08, 0.8)

    # ── Terreno ───────────────────────────────────────────────────────────
    traces.append(_box(lx0, ly0, lx1, ly1, -0.30, 0.0, "#27AE60",
                       opacity=0.55, name="Terreno", show_leg=True))

    # ── Sótanos ───────────────────────────────────────────────────────────
    for s in range(n_sotanos, 0, -1):
        z0 = -s * h_sotano
        z1 = -(s - 1) * h_sotano
        col = "#3C3C50" if (s % 2 == 0) else "#484860"
        traces.append(_box(hx0, hy0, hx1, hy1, z0, z1, col, opacity=0.88,
                           name="Sótanos" if s == n_sotanos else "",
                           show_leg=(s == n_sotanos)))
        # Label sótano
        traces.append(go.Scatter3d(
            x=[(hx0 + hx1) / 2], y=[lbl_y],
            z=[(z0 + z1) / 2],
            mode='text', text=[f"S{s}"],
            textfont=dict(size=9, color="#9090A8", family="Courier New, monospace"),
            showlegend=False, hoverinfo="skip", name="",
        ))

    # ── Pisos — subdivididos en celdas por departamento ───────────────────
    _tipo_legend_seen = set()
    _unit_label_xs, _unit_label_ys, _unit_label_zs, _unit_label_ts = [], [], [], []

    for p in range(n_pisos):
        z0 = p * h_piso
        z1 = (p + 1) * h_piso
        cells = _floor_cells.get(p, [])

        if cells:
            n_cells = len(cells)
            cell_w  = (bw - GAP * (n_cells - 1)) / n_cells
            for ci, (tipo, area) in enumerate(cells):
                cx0 = hx0 + ci * (cell_w + GAP)
                cx1 = cx0 + cell_w
                col = _TIPO_COLOR.get(tipo, _floor_color_gradient(p, n_pisos))
                leg = f"Tipo {tipo}"
                show_l = leg not in _tipo_legend_seen
                _tipo_legend_seen.add(leg)
                traces.append(_box(cx0, hy0, cx1, hy1, z0, z1,
                                   col, opacity=0.88,
                                   name=leg, show_leg=show_l,
                                   hover="text",
                                   customdata=f"Piso {p+1:02d} · Dpto {ci+1}<br>{tipo} · {area:.0f} m²"))
                # Label centrado dentro de la celda
                _unit_label_xs.append((cx0 + cx1) / 2)
                _unit_label_ys.append((hy0 + hy1) / 2)
                _unit_label_zs.append((z0 + z1) / 2)
                _unit_label_ts.append(tipo)
        else:
            # Sin datos de unidades — bloque sólido con gradiente
            col = _floor_color_gradient(p, n_pisos)
            traces.append(_box(hx0, hy0, hx1, hy1, z0, z1,
                               col, opacity=0.88,
                               name="Pisos", show_leg=(p == 0)))
            _unit_label_xs.append((hx0 + hx1) / 2)
            _unit_label_ys.append((hy0 + hy1) / 2)
            _unit_label_zs.append((z0 + z1) / 2)
            _unit_label_ts.append(f"P{p+1:02d}")

        # Label de piso (lado izquierdo del edificio)
        traces.append(go.Scatter3d(
            x=[hx0 - bw * 0.12], y=[lbl_y],
            z=[(z0 + z1) / 2],
            mode='text', text=[f"P{p+1:02d}"],
            textfont=dict(size=9, color=TEXT, family="Courier New, monospace"),
            showlegend=False, hoverinfo="skip", name="",
        ))

    # Labels de tipología dentro de cada celda (pequeño, centrado)
    if _unit_label_ts:
        traces.append(go.Scatter3d(
            x=_unit_label_xs, y=_unit_label_ys, z=_unit_label_zs,
            mode='text', text=_unit_label_ts,
            textfont=dict(size=9, color="rgba(255,255,255,0.85)",
                          family="Inter, sans-serif"),
            showlegend=False, hoverinfo="skip", name="",
        ))

    # ── Azotea cap — color diferenciado según tipología ───────────────────
    ax_m  = bw * 0.07
    ay_m  = bd * 0.07
    z_az0 = n_pisos * h_piso
    # Dúplex: azotea más alta (ocupa espacio de un piso completo)
    # Sin dúplex: azotea técnica delgada
    _az_h     = h_piso * 0.85 if _hay_duplex else max(h_piso * 0.45, 1.2)
    z_az1     = z_az0 + _az_h
    # Color: azotea habitable (dúplex) → naranja cálido; azotea técnica → dorado
    _az_color = _TIPO_COLOR["AZ_HAB"] if _hay_duplex else _TIPO_COLOR["AZ"]
    _az_label = "Azotea / Dúplex" if _hay_duplex else "Azotea"
    # Retranque mayor si hay dúplex (RNE A.020: 2.50m desde fachada)
    _ret_az   = max(bw * 0.12, 2.5) if _hay_duplex else ax_m
    _ret_az_y = max(bd * 0.12, 2.5) if _hay_duplex else ay_m
    traces.append(_box(
        hx0 + _ret_az, hy0 + _ret_az_y,
        hx1 - _ret_az, hy1 - _ret_az_y,
        z_az0, z_az1,
        _az_color, opacity=0.88,
        name=_az_label, show_leg=True,
    ))
    traces.append(go.Scatter3d(
        x=[hx0 - bw * 0.12], y=[lbl_y],
        z=[(z_az0 + z_az1) / 2],
        mode='text', text=["DUP" if _hay_duplex else "AZ"],
        textfont=dict(size=9,
                      color="#E67E22" if _hay_duplex else GOLD,
                      family="Courier New, monospace"),
        showlegend=False, hoverinfo="skip", name="",
    ))

    # ── Cotas de altura (derecha, solo cada 2 pisos) ──────────────────────
    cx    = hx1 + bw * 0.18
    step  = 1 if n_pisos <= 8 else 2
    cot_xs, cot_ys, cot_zs, cot_ts = [cx], [lbl_y], [0.0], ["±0.00"]
    for pp in range(n_pisos):
        if (pp + 1) % step == 0 or pp == n_pisos - 1:
            z_top = (pp + 1) * h_piso
            cot_xs.append(cx); cot_ys.append(lbl_y)
            cot_zs.append(z_top); cot_ts.append(f"+{z_top:.2f}")
    for ss in range(1, n_sotanos + 1):
        cot_xs.append(cx); cot_ys.append(lbl_y)
        cot_zs.append(-ss * h_sotano); cot_ts.append(f"{-ss*h_sotano:.2f}")
    traces.append(go.Scatter3d(
        x=cot_xs, y=cot_ys, z=cot_zs, mode='text', text=cot_ts,
        textfont=dict(size=8, color=GREY, family="Courier New, monospace"),
        showlegend=False, hoverinfo="skip", name="",
    ))

    # ── Línea ±0.00 (gold) ────────────────────────────────────────────────
    lx_line = hx0 - bw * 0.18
    traces.append(go.Scatter3d(
        x=[lx_line, cx], y=[lbl_y, lbl_y], z=[0.0, 0.0],
        mode='lines', line=dict(color=GOLD, width=3),
        showlegend=False, hoverinfo="skip", name="",
    ))

    # ── Layout ───────────────────────────────────────────────────────────
    h_total  = n_pisos * h_piso
    z_base   = -n_sotanos * h_sotano
    x_margin = bw * 0.35   # márgenes ajustados — sin espacio muerto

    bld_h = h_total + n_sotanos * h_sotano
    _ax   = 1.0
    _ay   = max(0.45, min(round(bd / bw, 2), 1.5)) if bw > 0 else 1.0
    _az   = min(round(bld_h / bw, 2), 1.1) if bw > 0 else 1.0

    fig = go.Figure(data=traces)
    fig.update_layout(
        scene=dict(
            xaxis=dict(visible=False, range=[hx0 - x_margin, hx1 + x_margin * 1.1]),
            yaxis=dict(visible=False, range=[ly0 - 3, ly1 + 3]),
            zaxis=dict(visible=False, range=[z_base - 1.5, h_total + 5]),
            bgcolor=BGND,
            aspectmode="manual",
            aspectratio=dict(x=_ax, y=_ay, z=_az),
            camera=dict(
                eye=dict(x=1.35, y=-1.05, z=0.70),  # más centrado — menos espacio muerto
                up=dict(x=0, y=0, z=1),
            ),
        ),
        paper_bgcolor=BGND,
        font=dict(color=TEXT, size=10, family="Inter, sans-serif"),
        margin=dict(l=0, r=0, t=10, b=10),
        height=600,
        legend=dict(
            x=0.01, y=0.97,
            bgcolor="rgba(240,242,246,0.92)",
            bordercolor="rgba(71,85,105,0.4)", borderwidth=1,
            font=dict(size=9, color=TEXT),
            itemsizing="constant",
            orientation="v",
        ),
        showlegend=True,
    )
    return fig


