# ═══════════════════════════════════════════════════════
# PRECIOS DE MERCADO — carga desde Google Sheet (con fallback)
# ═══════════════════════════════════════════════════════
_MERCADO_COLS = [
    "precio_1br","precio_2br","precio_3br",
    "precio_estac","precio_deposito","costo_construccion",
    "velocidad_venta","duracion_base_meses",
    "alquiler_m2_mes","yield_mercado_pct","variacion_anual_pct",
]
_MERCADO_INT_COLS  = {"precio_1br","precio_2br","precio_3br","precio_estac","precio_deposito",
                      "costo_construccion","duracion_base_meses"}
_MERCADO_FLOAT_COLS= {"velocidad_venta","alquiler_m2_mes","yield_mercado_pct","variacion_anual_pct"}

@st.cache_data(ttl=3600, show_spinner=False)
def _cargar_mercado_sheet() -> tuple:
    """Lee precios desde Google Sheet publicado como CSV. TTL 1 hora.
    Soporta dos formatos:
      - Nuevo (precio_m2_soles + alquiler_soles_100m2): convierte a USD usando tipo_cambio
      - Clásico (precio_1br, precio_2br, precio_3br en USD): usa directamente
    Fila especial CONFIG con columna tipo_cambio actualiza el tipo de cambio dinámicamente.
    Retorna (precios_dict, tipo_cambio).
    """
    _tc_secrets = float((st.secrets.get("mercado") or {}).get("tipo_cambio", 3.45))
    try:
        sheet_url = (st.secrets.get("mercado", {}) or {}).get("sheet_url", "")
        if not sheet_url:
            return {}, _tc_secrets
        import urllib.request, io as _io
        with urllib.request.urlopen(sheet_url, timeout=8) as resp:
            raw = resp.read().decode("utf-8")
        df = pd.read_csv(_io.StringIO(raw))
        df.columns = [c.strip().lower() for c in df.columns]
        if "distrito" not in df.columns:
            return {}, _tc_secrets
        # Leer tipo_cambio desde fila CONFIG
        tc = _tc_secrets
        if "tipo_cambio" in df.columns:
            cfg = df[df["distrito"].astype(str).str.strip().str.upper() == "CONFIG"]
            if not cfg.empty:
                try:
                    v = float(str(cfg.iloc[0]["tipo_cambio"]).replace(",","").strip())
                    if v > 0:
                        tc = v
                except (ValueError, TypeError):
                    pass
        use_soles = "precio_m2_soles" in df.columns
        out = {}
        for _, row in df.iterrows():
            distrito = str(row.get("distrito", "")).strip()
            if not distrito or distrito.lower() == "nan" or distrito.upper() == "CONFIG":
                continue
            entry = {}
            if use_soles:
                try:
                    base_s = float(str(row.get("precio_m2_soles","")).replace(",","").strip())
                    base_u = base_s / tc
                    entry["precio_1br"] = int(base_u * 1.10)
                    entry["precio_2br"] = int(base_u * 1.04)
                    entry["precio_3br"] = int(base_u * 0.96)
                except (ValueError, TypeError):
                    pass
                try:
                    alq = float(str(row.get("alquiler_soles_100m2","")).replace(",","").strip())
                    entry["alquiler_m2_mes"] = round(alq / 100 / tc, 2)
                except (ValueError, TypeError):
                    pass
                otros = ["precio_estac","precio_deposito","costo_construccion",
                         "velocidad_venta","duracion_base_meses",
                         "yield_mercado_pct","variacion_anual_pct"]
                for col in otros:
                    if col not in row:
                        continue
                    try:
                        val = float(str(row[col]).replace(",","").strip())
                        entry[col] = int(val) if col in _MERCADO_INT_COLS else round(val, 4)
                    except (ValueError, TypeError):
                        pass
            else:
                for col in _MERCADO_COLS:
                    if col not in row:
                        continue
                    try:
                        val = float(str(row[col]).replace(",","").strip())
                        entry[col] = int(val) if col in _MERCADO_INT_COLS else round(val, 4)
                    except (ValueError, TypeError):
                        pass
            if entry:
                out[distrito] = entry
        return out, tc
    except Exception as _e:
        _log.warning("_cargar_mercado_sheet falló — usando precios hardcoded (posiblemente desactualizados): %s", _e)
        return {}, _tc_secrets

@st.cache_data(ttl=300, show_spinner=False)
def get_mercado() -> tuple:
    """MERCADO actualizado: Sheet > hardcoded. Cacheado 5 min — no re-merge en cada rerun."""
    live, tc = _cargar_mercado_sheet()
    if not live:
        return MERCADO, tc
    merged = dict(MERCADO)
    for distrito, datos in live.items():
        if distrito in merged:
            merged[distrito] = {**merged[distrito], **datos}
        else:
            merged[distrito] = datos
    return merged, tc

@st.cache_data(ttl=3600, show_spinner=False)
def _cargar_mercado_supabase() -> dict:
    """Lee overrides de precios desde Supabase tabla mercado_precios. TTL 1h.
    Retorna dict {distrito: {campo: valor}} con solo los campos sobreescritos.
    """
    sb = _get_supabase()
    if not sb:
        return {}
    try:
        resp = _sb_exec(lambda: sb.table("mercado_precios").select("*").eq("activo", True).execute())
        rows = resp.data or []
        out = {}
        for row in rows:
            d = row.get("distrito")
            if not d:
                continue
            entry = {k: row[k] for k in _MERCADO_COLS if row.get(k) is not None}
            if entry:
                out[d] = entry
        return out
    except Exception as _e:
        _log.warning("_cargar_mercado_supabase: %s", _e)
        return {}


def _guardar_precio_supabase(distrito: str, campo: str, valor) -> bool:
    """Upsert un campo de precio para un distrito en Supabase. Devuelve True si tuvo éxito."""
    sb = _get_supabase()
    if not sb:
        return False
    try:
        # Busca registro existente
        resp = _sb_exec(lambda: sb.table("mercado_precios").select("id").eq("distrito", distrito).execute())
        rows = resp.data or []
        if rows:
            _sb_exec(lambda: sb.table("mercado_precios")
                     .update({campo: valor, "actualizado_en": datetime.datetime.utcnow().isoformat() + "Z"})
                     .eq("distrito", distrito).execute())
        else:
            _sb_exec(lambda: sb.table("mercado_precios")
                     .insert({"distrito": distrito, campo: valor, "activo": True,
                              "actualizado_en": datetime.datetime.utcnow().isoformat() + "Z",
                              "actualizado_por": st.session_state.get("_username", "admin")}).execute())
        _cargar_mercado_supabase.clear()   # invalidar caché
        get_mercado.clear()
        return True
    except Exception as _e:
        _log.error("_guardar_precio_supabase: %s", _e)
        return False


def _guardar_historial(modulo: str, distrito: str, tipo: str, kpis: dict, inputs_resumen=None) -> bool:
    """Guarda un registro de análisis en la tabla analisis_historial de Supabase."""
    try:
        sb = _get_supabase()
        if sb is None:
            return False
        import datetime as _dt_h, json as _j
        _usuario = ""
        try:
            _usuario = st.session_state.get("_user_name", "") or ""
        except Exception:
            pass
        # Serializar kpis — solo tipos básicos
        def _safe(v):
            if isinstance(v, (str, int, float, bool)) or v is None:
                return v
            try:
                return float(v)
            except Exception:
                return str(v)
        kpis_safe = {k: _safe(v) for k, v in (kpis or {}).items()}
        inp_safe  = {k: _safe(v) for k, v in (inputs_resumen or {}).items()}
        row = {
            "usuario":        _usuario[:100],
            "modulo":         modulo[:50],
            "distrito":       (distrito or "")[:100],
            "tipo":           (tipo or "")[:100],
            "kpis":           kpis_safe,
            "inputs_resumen": inp_safe,
        }
        sb.table("analisis_historial").insert(row).execute()
        return True
    except Exception as _e_h:
        _log.warning("_guardar_historial: %s", _e_h)
        return False


def _guardar_escenario(nombre: str, modulo: str, kpis: dict, inputs_resumen=None) -> None:
    """Guarda un escenario en st.session_state['_escenarios'] (máx 3)."""
    try:
        import streamlit as _st3
        _lista = _st3.session_state.get("_escenarios") or []
        if not isinstance(_lista, list):
            _lista = []
        # Evitar duplicados por nombre
        _lista = [e for e in _lista if e.get("nombre") != nombre]
        import datetime as _dt3
        _lista.insert(0, {
            "nombre":   nombre,
            "modulo":   modulo,
            "ts":       _dt3.datetime.now().strftime("%H:%M %d/%m"),
            "kpis":     {k: v for k, v in (kpis or {}).items()
                         if isinstance(v, (str, int, float, bool, type(None)))},
            "inputs":   {k: v for k, v in (inputs_resumen or {}).items()
                         if isinstance(v, (str, int, float, bool, type(None)))},
        })
        _st3.session_state["_escenarios"] = _lista[:3]  # máx 3
    except Exception as _e_esc:
        _log.warning("_guardar_escenario: %s", _e_esc)


# Tipo de cambio S./USD — se actualiza desde Sheet (fila CONFIG) o secrets.toml
TIPO_CAMBIO = float((st.secrets.get("mercado") or {}).get("tipo_cambio", 3.45))
# Sobrescribe MERCADO con versión live (Sheet > hardcoded, Supabase override > Sheet)
MERCADO, TIPO_CAMBIO = get_mercado()
# Aplicar overrides Supabase sobre MERCADO base
_sb_overrides = _cargar_mercado_supabase()
for _d, _v in _sb_overrides.items():
    if _d in MERCADO:
        MERCADO[_d] = {**MERCADO[_d], **_v}
    else:
        MERCADO[_d] = _v

# ═══════════════════════════════════════════════════════
# FONDO MIVIVIENDA — Parámetros 2025
# ═══════════════════════════════════════════════════════
_UIT_2025   = 5_350          # S/. — UIT vigente 2025
_TC_FMVF    = 3.75           # S/./USD referencial para topes FMVF
_FMVF_TOPE_UIT = 93.5        # Techo Crédito MiVivienda (Ley 30892)
_FMVF_TOPE_USD = round(_FMVF_TOPE_UIT * _UIT_2025 / _TC_FMVF)  # ≈ $133,393

# BBP — Bono del Buen Pagador (tramos 2025, en S/.)
# Fuente: FMVF — resolución de actualización vigente al momento de implementación
_BBP_TRAMOS = [
    # (precio_max_sol,  bono_sol,  descripcion)
    (93_100,   25_700, "Tramo 1 — hasta S/. 93,100 (≈17.4 UIT)"),
    (139_650,  17_400, "Tramo 2 — S/. 93,100–139,650 (hasta 26 UIT)"),
    (206_000,  10_700, "Tramo 3 — S/. 139,650–206,000 (hasta 38.5 UIT)"),
    (343_700,   5_500, "Tramo 4 — S/. 206,000–343,700 (hasta 64 UIT)"),
    (500_225,   3_900, "Tramo 5 — S/. 343,700–500,225 (hasta 93.5 UIT)"),
]

def _bbp_para_precio_sol(precio_sol: float) -> tuple:
    """Devuelve (bono_sol, descripcion) del tramo BBP para un precio en S/."""
    for tope, bono, desc in _BBP_TRAMOS:
        if precio_sol <= tope:
            return bono, desc
    return 0, "Fuera de rango FMVF (precio > 93.5 UIT)"

# ═══════════════════════════════════════════════════════
# CLAUDE API
# ═══════════════════════════════════════════════════════

def _sanitize_api_key(raw: str) -> str:
    """Strips non-ASCII characters that macOS autocorrect can silently inject."""
    return raw.encode("ascii", errors="ignore").decode("ascii").strip()


def _api_call(client, **kwargs) -> str:
    """Streaming API call — acumula chunks y detecta truncamiento por max_tokens."""
    chunks = []
    stop_reason = None
    try:
        with client.messages.stream(**kwargs) as stream:
            for chunk in stream.text_stream:
                chunks.append(chunk)
            try:
                stop_reason = stream.get_final_message().stop_reason
            except Exception:
                pass
    except Exception as _e:
        _se = str(_e)
        if "401" in _se or "authentication_error" in _se.lower() or "invalid x-api-key" in _se.lower():
            raise
        # Stream interrupted — NO usar respuesta parcial, reintentar completo
        raise ValueError(f"json_parse_error: Error de streaming ({_se[:150]})")

    if stop_reason == "max_tokens":
        raise ValueError("TRUNCADO_MAX_TOKENS: La respuesta fue cortada — aumenta max_tokens o reduce el input")

    text = "".join(chunks).strip()
    if not text:
        raise ValueError("json_parse_error: API devolvió respuesta vacía")
    return text


@st.cache_resource
def _make_anthropic_client(api_key: str) -> anthropic.Anthropic:
    return anthropic.Anthropic(
        api_key=api_key,
        max_retries=0,
        timeout=httpx.Timeout(connect=30.0, read=180.0, write=120.0, pool=30.0),
    )

def get_client():
    api_key = (
        os.environ.get("ANTHROPIC_API_KEY")
        or (st.secrets.get("anthropic", {}) or {}).get("api_key", "")
        or st.session_state.get("api_key_input", "")
    )
    if not api_key:
        st.error("⚠️ Clave API no configurada. Contacta al administrador.")
        st.stop()
    api_key = _sanitize_api_key(api_key)
    if not api_key.startswith("sk-"):
        st.error("🔑 Clave API inválida. Contacta al administrador.")
        st.stop()
    return _make_anthropic_client(api_key)


def _run_with_retry(fn, spinner_msg, max_attempts=3):
    """Ejecuta fn() reintentando en errores de red, servidor ocupado o rate limit."""
    _status = st.empty()
    last_err = ""
    is_rate_limit = False
    for attempt in range(1, max_attempts + 1):
        label = spinner_msg if attempt == 1 else f"{spinner_msg} — intento {attempt}/{max_attempts}"
        with st.spinner(label):
            try:
                result = fn()
                _status.empty()
                return result
            except Exception as e:
                last_err = str(e)
                err_lower = last_err.lower()

                # Errores fatales no reintentables — mostrar directo
                if "SOLUM_FATAL:" in last_err:
                    _status.empty()
                    st.error(last_err.replace("SOLUM_FATAL:", "⚠️"))
                    st.stop()

                # Auth error: clave inválida
                if "401" in last_err or "authentication_error" in err_lower or "invalid x-api-key" in err_lower or "invalid api key" in err_lower:
                    _status.empty()
                    st.session_state.pop("api_key_input", None)
                    st.error("🔑 Clave de acceso inválida. Ingresa una clave API válida en ⚙ Configuración e inténtalo de nuevo.")
                    st.stop()

                is_rate_limit = "429" in last_err or "rate_limit" in err_lower or "rate limit" in err_lower
                is_retriable = (
                    is_rate_limit
                    or "500" in last_err
                    or "529" in last_err
                    or "502" in last_err
                    or "503" in last_err
                    or "overloaded" in err_lower
                    or "bad gateway" in err_lower
                    or "internal server" in err_lower
                    or "connection" in err_lower
                    or "connect" in err_lower
                    or "timeout" in err_lower
                    or "timed out" in err_lower
                    or "network" in err_lower
                    or "remotedisconnected" in err_lower
                    or "read timeout" in err_lower
                    or "eoferror" in err_lower
                    or "reset by peer" in err_lower
                    or "ssl" in err_lower
                    or "json_parse_error" in err_lower
                    or "error de conexión" in err_lower
                    or "broken pipe" in err_lower
                    or "incomplete" in err_lower
                )
                if "TRUNCADO_MAX_TOKENS" in last_err:
                    _status.empty()
                    st.error("El análisis de documentos generó una respuesta demasiado larga. "
                             "Reduce el número de documentos adjuntos o intenta con menos páginas.")
                    st.stop()
                if not is_retriable:
                    _status.empty()
                    st.error(f"Error inesperado: {last_err[:400]}")
                    st.stop()

        if attempt < max_attempts:
            wait = 20 if is_rate_limit else 1
            for s in range(wait, 0, -1):
                msg = (f"Optimizando consulta — reintentando en {s}s… ({attempt + 1}/{max_attempts})"
                       if is_rate_limit else
                       f"Reintentando conexión… (intento {attempt + 1}/{max_attempts})")
                _status.info(msg)
                time.sleep(1)
            _status.empty()

    _status.empty()
    if "429" in last_err or "rate_limit" in last_err.lower():
        st.error("Se superó el límite de tokens de tu cuenta Anthropic. "
                 "Espera 1 minuto e inténtalo nuevamente.")
    elif "solum_fatal" in last_err.lower():
        st.error(last_err.replace("SOLUM_FATAL:", "⚠️"))
    elif "json_parse_error" in last_err.lower():
        # Mostrar el motivo real junto al mensaje genérico
        _detail = last_err.split("json_parse_error:")[-1].strip()[:200] if "json_parse_error:" in last_err else ""
        st.error(
            "El análisis no pudo completarse. "
            + (f"Detalle: {_detail} — " if _detail else "")
            + "Intenta nuevamente o sube documentos más ligeros (máx. 8 MB por archivo)."
        )
    else:
        st.error(
            f"No se pudo conectar con el servicio de análisis después de {max_attempts} intentos. "
            f"Verifica tu conexión e inténtalo nuevamente. ({last_err[:200]})"
        )
    st.stop()


def parse_json_safe(text: str) -> dict:
    """Extrae y parsea JSON de la respuesta de Claude. Lanza ValueError si falla."""
    # 1. Intentar extraer de bloque markdown ```json ... ```
    md_match = re.search(r'```(?:json)?\s*(\{.*?\})\s*```', text, re.DOTALL)
    if md_match:
        raw = md_match.group(1)
    else:
        # 2. Extraer el bloque JSON más externo { ... }
        brace_match = re.search(r'\{.*\}', text, re.DOTALL)
        if not brace_match:
            raise ValueError(f"json_parse_error: respuesta sin JSON — '{text[:120]}'")
        raw = brace_match.group()

    # Limpiar problemas comunes
    raw = re.sub(r'//[^\n]*', '', raw)
    raw = re.sub(r'/\*.*?\*/', '', raw, flags=re.DOTALL)
    raw = re.sub(r',\s*([\}\]])', r'\1', raw)
    raw = raw.replace('“', '"').replace('”', '"')
    raw = raw.replace('‘', "'").replace('’', "'")

    try:
        result = json.loads(raw)
        if not isinstance(result, dict) or len(result) == 0:
            raise ValueError(f"json_parse_error: JSON vacío o no es objeto")
        return result
    except json.JSONDecodeError as e:
        raise ValueError(f"json_parse_error: {e} — '{raw[:120]}'")


def _pdf_slice(pdf_bytes: bytes, page_indices: list[int]) -> bytes:
    """Extrae páginas específicas de un PDF usando pypdf. Devuelve bytes del nuevo PDF."""
    import io
    try:
        from pypdf import PdfReader, PdfWriter
        reader = PdfReader(io.BytesIO(pdf_bytes))
        writer = PdfWriter()
        n = len(reader.pages)
        for i in page_indices:
            if 0 <= i < n:
                writer.add_page(reader.pages[i])
        buf = io.BytesIO()
        writer.write(buf)
        return buf.getvalue()
    except ImportError:
        return pdf_bytes  # fallback: devolver completo


def pdf_block(pdf_bytes: bytes, max_pages: int = 4) -> dict:
    """Envía el PDF a la API. Si tiene más de max_pages páginas, recorta al inicio."""
    try:
        from pdfminer.pdfpage import PDFPage
        import io
        with io.BytesIO(pdf_bytes) as fh:
            n_pages = sum(1 for _ in PDFPage.get_pages(fh))
        if n_pages > max_pages:
            pdf_bytes = _pdf_slice(pdf_bytes, list(range(min(max_pages, n_pages))))
    except Exception:
        pass  # pdfminer no disponible — enviar completo
    return {
        "type": "document",
        "source": {
            "type": "base64",
            "media_type": "application/pdf",
            "data": base64.standard_b64encode(pdf_bytes).decode("utf-8")
        }
    }


def pdf_block_partida(pdf_bytes: bytes, head: int = 2, tail: int = 18) -> dict:
    """Extrae páginas óptimas de una Partida Registral SUNARP para análisis legal.

    Estrategia: primeras `head` páginas (portada + datos identificatorios) +
    últimas `tail` páginas (asientos electrónicos C00001/D00001 más recientes).
    Total máximo = head + tail páginas.

    Las partidas antiguas tienen páginas iniciales con escritura manuscrita/microfilmada
    (ficha en papel, pre-2000) de baja utilidad jurídica. Los asientos electrónicos al
    final del PDF reflejan el estado registral vigente y son la fuente primaria.
    """
    try:
        from pdfminer.pdfpage import PDFPage
        import io
        with io.BytesIO(pdf_bytes) as fh:
            n_pages = sum(1 for _ in PDFPage.get_pages(fh))

        max_total = head + tail
        if n_pages <= max_total:
            return pdf_block(pdf_bytes, max_pages=n_pages)  # PDF pequeño — enviar completo

        # PDF grande: primeras `head` + últimas `tail` páginas
        head_idx = list(range(head))
        tail_idx = list(range(max(head, n_pages - tail), n_pages))
        page_indices = sorted(set(head_idx + tail_idx))
        sliced = _pdf_slice(pdf_bytes, page_indices)
        _log.info("pdf_block_partida: %d páginas total → enviando %d (%d+%d seleccionadas)",
                  n_pages, len(page_indices), head, tail)
        return {
            "type": "document",
            "source": {
                "type": "base64",
                "media_type": "application/pdf",
                "data": base64.standard_b64encode(sliced).decode("utf-8")
            }
        }
    except Exception as _e:
        _log.warning("pdf_block_partida fallback completo: %s", _e)
        return pdf_block(pdf_bytes, max_pages=20)


def image_block(img_bytes: bytes, media_type: str = "image/jpeg") -> dict:
    return {
        "type": "image",
        "source": {
            "type": "base64",
            "media_type": media_type,
            "data": base64.standard_b64encode(img_bytes).decode("utf-8"),
        }
    }


def _resize_image(img_bytes: bytes, max_px: int = 1568) -> tuple[bytes, str]:
    """Redimensiona imagen a max_px en el lado mayor. Devuelve (bytes, media_type).
    1568px es el máximo recomendado por Anthropic para visión óptima con menor latencia."""
    try:
        from PIL import Image as _PIL_Image
        import io as _io
        img = _PIL_Image.open(_io.BytesIO(img_bytes))
        w, h = img.size
        orig_format = img.format or "JPEG"
        if max(w, h) > max_px:
            ratio = max_px / max(w, h)
            img = img.resize((int(w * ratio), int(h * ratio)), _PIL_Image.LANCZOS)
        # Convertir a RGB si tiene canal alpha (PNG con transparencia)
        if img.mode in ("RGBA", "P"):
            img = img.convert("RGB")
            out_format, media_type = "JPEG", "image/jpeg"
        elif orig_format == "PNG":
            out_format, media_type = "PNG", "image/png"
        else:
            out_format, media_type = "JPEG", "image/jpeg"
        buf = _io.BytesIO()
        img.save(buf, format=out_format, quality=85, optimize=True)
        return buf.getvalue(), media_type
    except Exception:
        return img_bytes, "image/jpeg"  # fallback sin modificar


def smart_block(file_bytes: bytes) -> dict:
    """Detecta por magic bytes si el archivo es PDF o imagen, redimensiona si es imagen
    y retorna el bloque correcto para la API de Claude."""
    if not file_bytes:
        return pdf_block(file_bytes)
    sig = file_bytes[:8]
    if sig[:4] == b"%PDF":
        return pdf_block(file_bytes)
    # Es imagen — redimensionar antes de enviar
    resized, media_type = _resize_image(file_bytes)
    return image_block(resized, media_type)


# ── CARGA DE NORMATIVAS DESDE ARCHIVOS EXTERNOS ─────────────────────────────────────────────────
@st.cache_data(ttl=3600, show_spinner=False)   # TTL 1 hora — refresca si normativa se actualiza en Supabase
def _load_norm(filename: str) -> str:
    """Carga normativa: Supabase (versión vigente) → archivo local → mensaje de error.
    @st.cache_data es global al proceso — una sola carga para todos los usuarios."""
    # 1. Intentar Supabase (versión activa más reciente)
    codigo = filename.replace(".txt", "").replace(".md", "")
    sb = _get_supabase()
    if sb:
        try:
            resp = (sb.table("normativas")
                      .select("contenido")
                      .eq("codigo", codigo)
                      .eq("activo", True)
                      .order("version", desc=True)
                      .limit(1)
                      .execute())
            if resp.data:
                return resp.data[0]["contenido"]
        except Exception:
            pass
    # 2. Fallback: archivo local
    path = pathlib.Path(__file__).parent / "normativas" / filename
    if path.exists():
        return path.read_text(encoding="utf-8")
    return f"[NORMATIVA NO ENCONTRADA: {filename}]"

