@st.cache_data(ttl=86400, show_spinner=False)
def _extract_cpue_fecha(doc_bytes: bytes) -> str | None:
    """Extracts CPUE emission date via Haiku. Cached by document content hash."""
    from datetime import datetime as _dt
    client = get_client()
    content = [
        smart_block(doc_bytes),
        {"type": "text", "text": (
            "Extrae la FECHA DE EMISIÓN del Certificado de Parámetros Urbanísticos y Edificatorios. "
            "Responde ÚNICAMENTE con la fecha en formato YYYY-MM-DD. "
            "Si no encuentras la fecha de emisión (no la de caducidad), responde exactamente: null"
        )},
    ]
    try:
        text = (_api_call(
            client,
            model="claude-haiku-4-5-20251001",
            max_tokens=30,
            messages=[{"role": "user", "content": content}],
        ) or "").strip()
        if text.lower() == "null" or not text:
            return None
        _dt.strptime(text, "%Y-%m-%d")
        return text
    except Exception:
        return None


def _cpue_vigencia_banner(fecha_emision: str | None) -> None:
    """Muestra alerta si el CPUE tiene más de 36 meses desde su emisión.
    Lima: Ley 29090 Art. 15 — el CPUE tiene una vigencia de 36 meses.
    Pasado ese plazo, los parámetros pueden haber cambiado por nueva ordenanza.
    """
    if not fecha_emision:
        return
    from datetime import date as _date, datetime as _datetime
    try:
        _emision = _datetime.strptime(fecha_emision, "%Y-%m-%d").date()
    except ValueError:
        return
    _hoy = _date.today()
    _meses_transcurridos = (_hoy.year - _emision.year) * 12 + (_hoy.month - _emision.month)
    if _meses_transcurridos >= 36:
        _color_bg  = "#FFF3E0" if _meses_transcurridos < 48 else "#FFF0F0"
        _color_bdr = "#F59E0B" if _meses_transcurridos < 48 else "#DC2626"
        _color_txt = "#92400E" if _meses_transcurridos < 48 else "#7F1D1D"
        _icon      = "⚠️" if _meses_transcurridos < 48 else "🔴"
        _anos_txt  = f"{_meses_transcurridos // 12} años {_meses_transcurridos % 12} meses"
        _nivel     = "VENCIDO" if _meses_transcurridos >= 48 else "PRÓXIMO A VENCER"
        st.markdown(
            f'<div style="background:{_color_bg};border-left:4px solid {_color_bdr};'
            f'border-radius:6px;padding:10px 16px;margin:8px 0;">'
            f'<span style="font-size:11px;font-weight:700;color:{_color_txt};">'
            f'{_icon} CPUE {_nivel} — Emitido: {fecha_emision} '
            f'({_anos_txt} atrás · vigencia legal: 36 meses · Ley 29090 Art. 15)</span><br>'
            f'<span style="font-size:10px;color:{_color_txt};opacity:0.85;">'
            f'Los parámetros urbanísticos pueden haber cambiado. '
            f'Solicitar CPUE actualizado a la municipalidad antes de comprometer la operación.'
            f'</span></div>',
            unsafe_allow_html=True
        )


@st.cache_data(ttl=1800, show_spinner=False)
def _get_normativas_post_cpue(fecha_emision: str, categorias: tuple) -> list:
    """Query alertas_normativas for records published after CPUE emission date."""
    sb = _get_supabase()
    if not sb or not fecha_emision:
        return []
    try:
        resp = (
            sb.table("alertas_normativas")
            .select("fecha_publicacion,entidad,tipo_norma,titulo,resumen,categorias,relevancia")
            .gte("fecha_publicacion", fecha_emision)
            .in_("relevancia", ["alta", "media"])
            .order("fecha_publicacion", desc=True)
            .limit(8)
            .execute()
        )
        rows = resp.data or []
        if categorias and rows:
            cat_set = {c.lower() for c in categorias}
            filtered = [
                r for r in rows
                if not r.get("categorias") or
                   bool(cat_set & {x.lower() for x in (r.get("categorias") or [])})
            ]
            return filtered if filtered else rows
        return rows
    except Exception as _e:
        _log.warning("_get_normativas_post_cpue falló — usuario no verá alertas normativas: %s", _e)
        return []


