        f'<div style="font-size:22px;font-weight:800;color:#0D2137;">${_pie:,.0f}</div>'
        f'<div style="font-size:10px;color:#6B7280;margin-top:3px;">{_pct_pie:.0f}% del precio</div>'
        '</div>'
