def generar_informe_html(params, cabida, financ, legal, zona, financ_inputs, fecha):
    """Genera informe HTML SOLUM 3 páginas (portada + cabida + financiero/legal)."""
    def _e(s): return _html_esc.escape(str(s or ""))

    # ── Top-level data unpacking ─────────────────────────────
    r   = (financ or {}).get("resumen", {}) if financ else {}
    fi  = financ_inputs or {}
    p   = params or {}
    c   = cabida or {}
    leg = legal  or {}

    # ── Flujo de caja ────────────────────────────────────────
    tir_real = mes_be = max_exp = None
    if cabida and financ:
        m_data = MERCADO.get(zona, {})
        fin_fl = {
            "costo_terreno":      fi.get("costo_terreno", 0),
            "costo_construccion": fi.get("costo_construccion", m_data.get("costo_construccion", 0)),
            "costo_sotano_m2":    fi.get("costo_sotano_m2", 450),
            "fee_constructora":   fi.get("fee_constructora", 10.0),
            "tasa_ir":            fi.get("tasa_ir", 29.5),
            "include_alcabala":   fi.get("include_alcabala", True),
            "include_dd":         fi.get("include_dd", True),
            "precio_venta_m2":    fi.get("precio_venta_m2", m_data.get("precio_2br", 0)),
            "precio_estac":       m_data.get("precio_estac", 0),
            "precio_deposito":    m_data.get("precio_deposito", 0),
            "tasa_financ":        fi.get("tasa_financ", 9.0),
        }
        result_fl = calcular_financiero(cabida, fin_fl, zona)
        try:
            _, _, tir_real, mes_be, max_exp, _ = generar_flujo(cabida, result_fl, fin_fl, zona)
        except Exception:
            pass

    _score_r = score_viabilidad(r) if r else (0, 0, "—", "", "", "—", [])
    pts, score_10, etiqueta, _, _, recomendacion, score_items = _score_r

    # ── Data shortcuts ───────────────────────────────────────
    ubicacion    = _e(p.get("ubicacion", "—"))
    zonificacion = _e(p.get("zonificacion", "—"))
    area_t_raw   = p.get("area_terreno_m2", "—")
    pisos_max_raw = p.get("pisos_max", "—")
    area_libre_raw = p.get("area_libre_min_pct", "—")
    retiro_raw   = p.get("retiro_frontal_ml", p.get("retiro_frontal", "—"))
    coef_raw     = p.get("coeficiente_edificacion", "—")

    area_t        = _e(f"{area_t_raw} m²")
    pisos_max_v   = _e(f"{pisos_max_raw} pisos")
    area_libre_v  = _e(f"{area_libre_raw}%")
    retiro_v      = _e(f"{retiro_raw} ml")
    coef_v        = _e(str(coef_raw))

    at_total  = c.get("area_techada_total_m2") or 0
    av_total  = c.get("area_vendible_m2") or 0
    n_unid    = c.get("n_unidades") or c.get("total_unidades") or "—"
    n_pisos_c = c.get("n_pisos") or c.get("num_pisos") or "—"
    n_sot     = c.get("n_sotanos") or c.get("num_sotanos") or 0
    estac     = c.get("estacionamientos") or c.get("estac_total") or "—"
    efic      = f"{round(av_total / at_total * 100, 1)}%" if at_total else "—"

    ing_brutos   = r.get("ingresos_brutos", 0) or 0
    costo_total  = r.get("costo_total", 0) or 0
    margen_pct   = r.get("margen_pct", 0) or 0
    tir_pct      = r.get("tir_anual_pct", 0) or 0
    util_neta    = r.get("utilidad_neta", 0) or 0
    pv_m2        = r.get("precio_venta_m2", 0) or 0
    ct_terreno   = r.get("costo_terreno", fi.get("costo_terreno", 0)) or 0
    ct_constr    = (costo_total - ct_terreno) if costo_total else 0
    ct_total_pct_terr = f"{ct_terreno / costo_total * 100:.1f}%" if costo_total else "—"
    ct_total_pct_con  = f"{ct_constr  / costo_total * 100:.1f}%" if costo_total else "—"
    max_terr_20  = r.get("max_terreno_20pct", 0) or 0
    max_terr_25  = r.get("max_terreno_25pct", 0) or 0

    tir_str = f"{tir_real}%" if tir_real is not None else "—"
    exp_str = fmt_usd(abs(max_exp)) if max_exp is not None else "—"
    be_str  = f"Mes {mes_be}" if mes_be else "—"

    sem_raw   = leg.get("semaforo", "")
    sem_color = {"verde": "#1A7A4A", "amarillo": "#B8862E", "rojo": "#8B1A1A"}.get(sem_raw, "#4A5568")
    sem_label = {
        "verde":    "SIN ALERTAS CRÍTICAS",
        "amarillo": "ALERTAS MENORES",
        "rojo":     "ALERTAS CRÍTICAS",
    }.get(sem_raw, "Análisis legal no ejecutado")
    res_legal = _e(leg.get("resumen_legal") or "")

    alertas_html = ""
    for _a in leg.get("alertas", []):
        alertas_html += (
            f'<li style="font-size:10.5px;color:#7B1A1A;margin:3px 0;">'
            f'{_e(str(_a))}</li>'
        )
    if alertas_html:
        alertas_html = f'<ul style="margin:6px 0 0 18px;padding:0;">{alertas_html}</ul>'

    # score items table rows
    score_rows_html = ""
    for si in (score_items or []):
        _nom = _e(si.get("nombre", ""))
        _not = _e(si.get("nota", ""))
        score_rows_html += (
            f'<tr>'
            f'<td style="padding:5px 10px;font-size:10.5px;color:#1E2D3D;border-bottom:1px solid #E2E8F0;">{_nom}</td>'
            f'<td style="padding:5px 10px;font-size:10.5px;color:#4A5568;border-bottom:1px solid #E2E8F0;">{_not}</td>'
            f'</tr>'
        )

    # ── Isotipo SVG ──────────────────────────────────────────
    ISOTIPO_48 = (
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="237 -2 411 837" '
        'style="height:48px;display:block;margin-bottom:6px;">'
        '<rect fill="#1E2D3D" x="239.53" y="660.47" width="17.59" height="172.62" rx="8.79" ry="8.79"/>'
        '<rect fill="#1E2D3D" x="289.66" y="513.49" width="13.7"  height="318.98" rx="6.85" ry="16.25"/>'
        '<rect fill="#1E2D3D" x="338.93" y="368.79" width="13.7"  height="463.69" rx="6.85" ry="23.62"/>'
        '<rect fill="#1E2D3D" x="389.88" y="442.34" width="13.7"  height="390.14" rx="6.85" ry="19.88"/>'
        '<rect fill="#1E2D3D" x="435.62" y="583.81" width="13.7"  height="248.66" rx="6.85" ry="12.67"/>'
        '<rect fill="#1E2D3D" x="485.6"  y="512.66" width="13.7"  height="319.81" rx="6.85" ry="16.29"/>'
        '<rect fill="#1E2D3D" x="534.3"  y="367.3"  width="13.7"  height="465.17" rx="6.85" ry="23.7"/>'
        '<rect fill="#1E2D3D" x="583.52" y="222.58" width="13.7"  height="609.89" rx="6.85" ry="31.07"/>'
        '<rect fill="#1E2D3D" x="632.05" y="0"      width="13.7"  height="832.47" rx="6.85" ry="42.41"/>'
        '</svg>'
    )
    ISOTIPO_36 = (
        '<svg xmlns="http://www.w3.org/2000/svg" viewBox="237 -2 411 837" '
        'style="height:36px;display:block;">'
        '<rect fill="#1E2D3D" x="239.53" y="660.47" width="17.59" height="172.62" rx="8.79" ry="8.79"/>'
        '<rect fill="#1E2D3D" x="289.66" y="513.49" width="13.7"  height="318.98" rx="6.85" ry="16.25"/>'
        '<rect fill="#1E2D3D" x="338.93" y="368.79" width="13.7"  height="463.69" rx="6.85" ry="23.62"/>'
        '<rect fill="#1E2D3D" x="389.88" y="442.34" width="13.7"  height="390.14" rx="6.85" ry="19.88"/>'
        '<rect fill="#1E2D3D" x="435.62" y="583.81" width="13.7"  height="248.66" rx="6.85" ry="12.67"/>'
        '<rect fill="#1E2D3D" x="485.6"  y="512.66" width="13.7"  height="319.81" rx="6.85" ry="16.29"/>'
        '<rect fill="#1E2D3D" x="534.3"  y="367.3"  width="13.7"  height="465.17" rx="6.85" ry="23.7"/>'
        '<rect fill="#1E2D3D" x="583.52" y="222.58" width="13.7"  height="609.89" rx="6.85" ry="31.07"/>'
        '<rect fill="#1E2D3D" x="632.05" y="0"      width="13.7"  height="832.47" rx="6.85" ry="42.41"/>'
        '</svg>'
    )

    # ── Score table (pre-built to avoid nested f-string complexity) ─────────
    _score_table = (
        '<table style="width:100%;border-collapse:collapse;">'
        '<thead><tr>'
        '<th style="font-size:11px;font-weight:700;color:#718096;text-transform:uppercase;'
        'padding:5px 10px;border-bottom:2px solid #D1D9E6;text-align:left;">Indicador</th>'
        '<th style="font-size:11px;font-weight:700;color:#718096;text-transform:uppercase;'
        'padding:5px 10px;border-bottom:2px solid #D1D9E6;text-align:left;">Evaluación</th>'
        '</tr></thead>'
        f'<tbody>{score_rows_html}</tbody></table>'
    ) if score_rows_html else (
        '<p style="font-size:10.5px;color:#718096;">'
        'Datos financieros insuficientes para calcular score de viabilidad.</p>'
    )

    _legal_block = (
        f'<table style="width:100%;border-collapse:collapse;">'
        f'<tr><td style="padding:6px 12px;font-weight:600;color:#0D2137;width:42%;'
        f'background:#F7F9FC;border-bottom:1px solid #D1D9E6;font-size:10.5px;">Resumen legal</td>'
        f'<td style="padding:6px 12px;font-size:10.5px;border-bottom:1px solid #D1D9E6;">'
        f'{res_legal}</td></tr></table>'
        f'{alertas_html}'
    ) if leg else (
        '<p style="font-size:10.5px;color:#718096;">'
        'Análisis legal no ejecutado en esta sesión.</p>'
    )

    # ── HTML ─────────────────────────────────────────────────
    html = f"""<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<title>SOLUM — Análisis de Proyecto Inmobiliario</title>
<style>
  @import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');
  :root {{
    --navy:    #0D2137;
    --navy2:   #1E2D3D;
    --gold:    #C9A96E;
    --gray-bg: #F7F9FC;
    --page-bg: #E8ECF2;
    --border:  #D1D9E6;
    --text:    #2D3748;
    --muted:   #718096;
  }}
  * {{ box-sizing: border-box; margin: 0; padding: 0; }}
  body {{
    font-family: 'Inter', 'Helvetica Neue', Arial, sans-serif;
    background: var(--page-bg);
    color: var(--text);
    font-size: 11px;
    line-height: 1.6;
  }}
  .page {{
    background: #fff;
    width: 794px;
    min-height: 1123px;
    margin: 0 auto 32px;
    padding: 0 0 72px;
    border-top: 8px solid var(--navy2);
    position: relative;
  }}
  .page-inner {{ padding: 36px 48px 0; }}
  .page-header {{
    display: flex;
    justify-content: space-between;
    align-items: flex-end;
    padding-bottom: 14px;
    margin-bottom: 28px;
    border-bottom: 1.5px solid var(--border);
  }}
  .page-header-logo {{ display: flex; align-items: flex-end; gap: 10px; }}
  .solum-word {{
    font-size: 17px; font-weight: 800; color: var(--navy);
    letter-spacing: -0.5px; line-height: 1; margin-bottom: 2px;
  }}
  .page-header-meta {{
    text-align: right; font-size:11px; color: var(--muted); line-height: 1.5;
  }}
  .sec-title {{
    font-size:11px; font-weight: 700; color: var(--navy);
    text-transform: uppercase; letter-spacing: 1.5px;
    padding-bottom: 6px; margin-bottom: 12px;
    border-bottom: 2px solid var(--navy2);
    position: relative;
  }}
  .sec-title::after {{
    content: ""; position: absolute;
    left: 0; right: 0; bottom: -1px;
    height: 1px; background: var(--border);
  }}
  .section {{ margin-bottom: 28px; }}
  .kv-table {{ width: 100%; border-collapse: collapse; }}
  .kv-table td {{
    padding: 6px 12px; font-size: 10.5px;
    border-bottom: 1px solid var(--border); vertical-align: top;
  }}
  .kv-table td:first-child {{
    font-weight: 600; color: var(--navy);
    width: 42%; background: var(--gray-bg);
  }}
  .kv-table tr:nth-child(even) td {{ background: #fff; }}
  .kv-table tr:nth-child(even) td:first-child {{ background: #fff; }}
  .kpi-strip {{ display: flex; gap: 12px; }}
  .kpi-card {{
    flex: 1; background: var(--gray-bg);
    border: 1px solid var(--border); border-radius: 6px;
    padding: 14px 16px; text-align: center;
  }}
  .kpi-label {{
    font-size:11px; font-weight: 600;
    text-transform: uppercase; letter-spacing: 1px;
    color: var(--muted); margin-bottom: 6px;
  }}
  .kpi-value {{
    font-size: 16px; font-weight: 800;
    color: var(--navy); line-height: 1.1;
  }}
  .cost-table {{ width: 100%; border-collapse: collapse; }}
  .cost-table th {{
    font-size:11px; font-weight: 700; color: var(--muted);
    text-transform: uppercase; letter-spacing: 1px;
    padding: 6px 12px; border-bottom: 2px solid var(--border); text-align: left;
  }}
  .cost-table td {{ padding: 6px 12px; font-size: 10.5px; border-bottom: 1px solid var(--border); }}
  .cost-table tr.total-row td {{
    font-weight: 700; color: var(--navy);
    border-top: 2px solid var(--navy2); border-bottom: none;
    background: var(--gray-bg);
  }}
  .badge {{
    display: inline-block; padding: 4px 12px; border-radius: 20px;
    font-size:11px; font-weight: 700;
    text-transform: uppercase; letter-spacing: 1px;
  }}
  .page-footer {{
    position: absolute; bottom: 20px; left: 48px; right: 48px;
    display: flex; justify-content: space-between; align-items: flex-end;
    border-top: 1px solid var(--border); padding-top: 12px;
  }}
  .footer-sig {{ font-size: 10px; color: var(--navy); line-height: 1.5; }}
  .sig-name {{ font-weight: 700; }}
  .footer-disc {{ font-size:11px; color: var(--muted); text-align: right; line-height: 1.4; }}
  @media print {{
    body {{ background: #fff; }}
    .page {{ margin: 0; page-break-after: always; }}
    .page:last-child {{ page-break-after: auto; }}
  }}
</style>
</head>
<body>

<!-- ══════════════════════════════════════════════════════════
     PÁGINA 1 — PORTADA
     ══════════════════════════════════════════════════════════ -->
<div class="page">
  <div style="padding:36px 48px 0;display:flex;justify-content:space-between;align-items:flex-start;">
    <div style="display:flex;flex-direction:column;align-items:flex-start;">
      {ISOTIPO_48}
      <div style="font-size:22px;font-weight:800;color:var(--navy);letter-spacing:-1px;line-height:1;">SOLUM</div>
      <div style="font-size:11px;color:var(--gold);letter-spacing:2.5px;text-transform:uppercase;font-weight:600;margin-top:3px;">Análisis Inmobiliario</div>
    </div>
    <div style="text-align:right;padding-top:6px;">
      <div style="font-size:11px;color:var(--muted);font-weight:500;">{_e(fecha)}</div>
      <div style="font-size:10px;color:var(--navy);font-weight:600;margin-top:4px;">{_e(zona or "—")}</div>
      <div style="font-size:11px;color:var(--muted);margin-top:2px;">Osterling Advisory</div>
    </div>
  </div>

  <div style="margin:24px 48px;height:1.5px;background:var(--border);"></div>

  <div style="padding:0 48px;margin-bottom:40px;">
    <div style="font-size:26px;font-weight:800;color:var(--navy);line-height:1.2;margin-bottom:8px;">{ubicacion}</div>
    <div style="font-size:13px;font-weight:500;color:var(--muted);">Análisis de Proyecto Inmobiliario</div>
    <div style="margin-top:16px;display:flex;gap:12px;flex-wrap:wrap;">
      <span style="font-size:11px;background:var(--gray-bg);border:1px solid var(--border);border-radius:4px;padding:3px 10px;color:var(--navy);font-weight:600;">{zonificacion}</span>
      <span style="font-size:11px;background:var(--gray-bg);border:1px solid var(--border);border-radius:4px;padding:3px 10px;color:var(--navy);font-weight:600;">{area_t}</span>
      <span style="font-size:11px;background:var(--gray-bg);border:1px solid var(--border);border-radius:4px;padding:3px 10px;color:var(--navy);font-weight:600;">{pisos_max_v}</span>
    </div>
  </div>

  <div style="padding:0 48px;">
    <div class="kpi-strip">
      <div class="kpi-card">
        <div class="kpi-label">Área Terreno</div>
        <div class="kpi-value">{area_t}</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Ingresos Brutos</div>
        <div class="kpi-value" style="font-size:13px;">{_e(fmt_usd(ing_brutos))}</div>
      </div>
      <div class="kpi-card">
        <div class="kpi-label">Costo Total</div>
        <div class="kpi-value" style="font-size:13px;">{_e(fmt_usd(costo_total))}</div>
      </div>
      <div class="kpi-card" style="border-color:var(--gold);background:#FEFBF3;">
        <div class="kpi-label" style="color:var(--gold);">Margen Neto</div>
        <div class="kpi-value" style="color:var(--gold);">{_e(f"{margen_pct:.1f}%")}</div>
      </div>
    </div>
  </div>

  <div class="page-footer">
    <div class="footer-sig">
      <div class="sig-name">Enrique Osterling</div>
      <div style="color:var(--muted);">Director General · Osterling Advisory</div>
    </div>
    <div class="footer-disc">
      Resultados referenciales — validar con asesores especializados.<br>
      Generado con SOLUM &copy; 2026 · Osterling Advisory
    </div>
  </div>
</div>


<!-- ══════════════════════════════════════════════════════════
     PÁGINA 2 — PARÁMETROS Y CABIDA
     ══════════════════════════════════════════════════════════ -->
<div class="page">
  <div class="page-inner">
    <div class="page-header">
      <div class="page-header-logo">
        {ISOTIPO_36}
        <div>
          <div class="solum-word">SOLUM</div>
          <div style="font-size:11px;color:var(--gold);letter-spacing:2px;text-transform:uppercase;font-weight:600;">Análisis Inmobiliario</div>
        </div>
      </div>
      <div class="page-header-meta">
        Análisis Proyecto Inmobiliario<br>{_e(fecha)}
      </div>
    </div>

    <div class="section">
      <div class="sec-title">Parámetros Urbanísticos</div>
      <table class="kv-table">
        <tr><td>Ubicación</td><td>{ubicacion}</td></tr>
        <tr><td>Zonificación</td><td>{zonificacion}</td></tr>
        <tr><td>Área del terreno</td><td>{area_t}</td></tr>
        <tr><td>Altura máxima</td><td>{pisos_max_v}</td></tr>
        <tr><td>Área libre mínima</td><td>{area_libre_v}</td></tr>
        <tr><td>Retiro frontal</td><td>{retiro_v}</td></tr>
        <tr><td>Coeficiente de edificación</td><td>{coef_v}</td></tr>
      </table>
    </div>

    <div class="section">
      <div class="sec-title">Programa Arquitectónico</div>
      <table class="kv-table">
        <tr><td>Pisos / Sótanos</td><td>{_e(str(n_pisos_c))} pisos · {_e(str(n_sot))} sótanos</td></tr>
        <tr><td>Área techada total</td><td>{_e(f"{at_total:,.0f} m²")}</td></tr>
        <tr><td>Área vendible</td><td>{_e(f"{av_total:,.0f} m²")}</td></tr>
        <tr><td>Eficiencia</td><td>{_e(efic)}</td></tr>
        <tr><td>Unidades de vivienda</td><td>{_e(str(n_unid))}</td></tr>
        <tr><td>Estacionamientos</td><td>{_e(str(estac))}</td></tr>
      </table>
    </div>

    <div class="section">
      <div class="sec-title">Indicadores Financieros</div>
      <div class="kpi-strip">
        <div class="kpi-card">
          <div class="kpi-label">Margen Neto</div>
          <div class="kpi-value">{_e(f"{margen_pct:.1f}%")}</div>
        </div>
        <div class="kpi-card">
          <div class="kpi-label">TIR Anual</div>
          <div class="kpi-value">{_e(f"{tir_pct:.1f}%")}</div>
        </div>
        <div class="kpi-card">
          <div class="kpi-label">Utilidad Neta</div>
          <div class="kpi-value" style="font-size:13px;">{_e(fmt_usd(util_neta))}</div>
        </div>
        <div class="kpi-card">
          <div class="kpi-label">Precio / m²</div>
          <div class="kpi-value" style="font-size:13px;">{_e(fmt_usd(pv_m2))}</div>
        </div>
      </div>
    </div>
  </div>

  <div class="page-footer">
    <div class="footer-sig">
      <div class="sig-name">Enrique Osterling</div>
      <div style="color:var(--muted);">Director General · Osterling Advisory</div>
    </div>
    <div class="footer-disc">
      Resultados referenciales — validar con asesores especializados.<br>
      Generado con SOLUM &copy; 2026 · Osterling Advisory
    </div>
  </div>
</div>


<!-- ══════════════════════════════════════════════════════════
     PÁGINA 3 — FINANCIERO Y LEGAL
     ══════════════════════════════════════════════════════════ -->
<div class="page">
  <div class="page-inner">
    <div class="page-header">
      <div class="page-header-logo">
        {ISOTIPO_36}
        <div>
          <div class="solum-word">SOLUM</div>
          <div style="font-size:11px;color:var(--gold);letter-spacing:2px;text-transform:uppercase;font-weight:600;">Análisis Inmobiliario</div>
        </div>
      </div>
      <div class="page-header-meta">
        Análisis Proyecto Inmobiliario<br>{_e(fecha)}
      </div>
    </div>

    <div class="section">
      <div class="sec-title">Estructura de Costos</div>
      <table class="cost-table">
        <thead>
          <tr>
            <th>Componente</th>
            <th style="text-align:right;">Monto (USD)</th>
            <th style="text-align:right;">% Total</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td>Terreno</td>
            <td style="text-align:right;">{_e(fmt_usd(ct_terreno))}</td>
            <td style="text-align:right;">{_e(ct_total_pct_terr)}</td>
          </tr>
          <tr>
            <td>Construcción y otros</td>
            <td style="text-align:right;">{_e(fmt_usd(ct_constr))}</td>
            <td style="text-align:right;">{_e(ct_total_pct_con)}</td>
          </tr>
          <tr class="total-row">
            <td>Total</td>
            <td style="text-align:right;">{_e(fmt_usd(costo_total))}</td>
            <td style="text-align:right;">100%</td>
          </tr>
        </tbody>
      </table>
      <div style="margin-top:10px;font-size:11px;color:var(--muted);">
        Precio máximo terreno (20%): <strong style="color:var(--navy);">{_e(fmt_usd(max_terr_20))}</strong>
        &nbsp;·&nbsp;
        Precio máximo terreno (25%): <strong style="color:var(--navy);">{_e(fmt_usd(max_terr_25))}</strong>
      </div>
    </div>

    <div class="section">
      <div class="sec-title">Viabilidad del Proyecto</div>
      {_score_table}
      <div style="margin-top:10px;background:var(--gray-bg);border:1px solid var(--border);border-radius:5px;padding:10px 14px;">
        <div style="font-size:11px;font-weight:600;color:var(--muted);text-transform:uppercase;letter-spacing:1px;margin-bottom:4px;">TIR · Exposición · Break-even</div>
        <div style="font-size:10.5px;color:var(--navy);">
          TIR numérica: <strong>{_e(tir_str)}</strong>&nbsp;&nbsp;·&nbsp;&nbsp;
          Exposición máxima: <strong>{_e(exp_str)}</strong>&nbsp;&nbsp;·&nbsp;&nbsp;
          Break-even: <strong>{_e(be_str)}</strong>
        </div>
      </div>
    </div>

    <div class="section">
      <div class="sec-title">Análisis Legal</div>
      <div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;">
        <span class="badge" style="background:{_e(sem_color)}1A;color:{_e(sem_color)};border:1px solid {_e(sem_color)};">{_e(sem_label)}</span>
      </div>
      {_legal_block}
    </div>
  </div>

  <div class="page-footer">
    <div class="footer-sig">
      <div class="sig-name">Enrique Osterling</div>
      <div style="color:var(--muted);">Director General · Osterling Advisory</div>
      <div style="color:var(--muted);">eosterling@grupoosterling.com</div>
    </div>
    <div class="footer-disc">
      Resultados referenciales — validar con asesores especializados.<br>
      Generado con SOLUM &copy; 2026 · Osterling Advisory
    </div>
  </div>
</div>

</body></html>"""
    return html


# ═══════════════════════════════════════════════════════
# APP PRINCIPAL
# ═══════════════════════════════════════════════════════

_module_subtitles = {
    "Proyecto Inmobiliario":          "IA de Análisis Inmobiliario",
    "Proyecto Logístico / Industrial": "Análisis de Inmuebles para el Desarrollo de Actividades Logísticas e Industriales",
    "Inmueble Residencial":            "Evaluación de Inmuebles Residenciales",
}
_active_module = st.session_state.get("tipo_operacion", "Proyecto Inmobiliario")
_subtitle = _module_subtitles.get(_active_module, "IA de Análisis Inmobiliario")
_module_tags = {
    "Proyecto Inmobiliario":          "Cabida · Financiero · Legal · Asistente",
    "Proyecto Logístico / Industrial": "Costo · Yield · DSCR · Comparativa",
    "Inmueble Residencial":            "Crédito · Inversión · Amortización",
}
_tag = _module_tags.get(_active_module, "")

st.markdown(
    '<div class="main-header">'
    '<div style="display:flex;align-items:center;justify-content:space-between;">'
    '<div style="display:flex;align-items:center;gap:0;">'
    '<div style="border-right:1px solid rgba(71,85,105,0.14);padding-right:20px;margin-right:20px;">'
    '<div style="font-family:Cinzel,serif;font-size:17px;font-weight:700;color:#0D2137;'
    'letter-spacing:3px;line-height:1;">SOLUM</div>'
    '</div>'
    '<div>'
    '<div style="font-size:10px;color:rgba(71,85,105,0.55);letter-spacing:4px;'
    'text-transform:uppercase;font-weight:700;margin-bottom:4px;">Osterling Advisory</div>'
    f'<div style="font-size:12px;font-weight:500;color:#0D2137;letter-spacing:2px;'
    f'text-transform:uppercase;line-height:1.3;">{_subtitle}</div>'
    '</div>'
    '</div>'
    '<div style="text-align:right;">'
    '<div style="font-size:10px;color:rgba(71,85,105,0.45);letter-spacing:3px;'
    'text-transform:uppercase;font-weight:600;">Lima, Perú</div>'
    f'<div style="font-size:10px;color:#6B7280;margin-top:4px;'
    f'letter-spacing:1.5px;text-transform:uppercase;">{_active_module}</div>'
    '</div>'
    '</div></div>',
    unsafe_allow_html=True
)

# ── SIDEBAR ──────────────────────────────────────────

run = False
run_industrial = False
run_residencial = False
run_ind_docs = False
run_res_docs = False
run_oficinas = False

with st.sidebar:
    # ── Logo SOLUM (top del sidebar) ──────────────────
    _logo_sidebar = (
        f'<img src="data:image/svg+xml;base64,{_SOLUM_SVG_WHITE_B64}" '
        f'style="width:130px;height:auto;display:block;margin:0 auto;" />'
        if _SOLUM_SVG_WHITE_B64 else
        '<div style="font-family:Cinzel,serif;font-size:22px;font-weight:700;'
        'color:#FFFFFF;text-align:center;letter-spacing:3px;">SOLUM</div>'
    )
    st.markdown(
        f'<div style="padding:16px 20px 18px;border-bottom:1px solid rgba(255,255,255,0.09);'
        f'margin-bottom:6px;text-align:center;">'
        f'{_logo_sidebar}'
        f'</div>',
        unsafe_allow_html=True)

    # ── Usuario activo ─────────────────────────────────
    _user_display = st.session_state.get("_user_name", "")
    _user_role    = st.session_state.get("_user_role", "advisor")
    _role_label = "Admin" if _user_role == "admin" else "Asesor"
    st.markdown(
        f'<div style="padding:10px 14px 6px;">'
        f'<div style="font-size:13px;font-weight:700;color:#FFFFFF;margin-bottom:1px;">{_user_display}</div>'
        f'<div style="font-size:10px;color:rgba(255,255,255,0.45);letter-spacing:2px;text-transform:uppercase;font-weight:600;">{_role_label}</div>'
        f'</div>',
        unsafe_allow_html=True)
    if st.button("Cerrar sesión", key="_logout_btn", use_container_width=True):
        for k in ["_authenticated","_user_name","_user_role","_username"]:
            st.session_state.pop(k, None)
        st.rerun()

    # ── Eliminar cuenta (GDPR / CCPA / Apple App Store 5.1.1v) ──────────────
    with st.expander("⚠ Eliminar cuenta", expanded=False):
        st.markdown(
            '<div style="font-size:11px;color:rgba(255,255,255,0.55);line-height:1.5;margin-bottom:8px;">'
            'Esta acción anonimiza tus datos y bloquea el acceso de forma permanente. '
            'No es reversible.'
            '</div>',
            unsafe_allow_html=True,
        )
        _del_confirm = st.text_input(
            "Escribe ELIMINAR para confirmar",
            key="_delete_confirm_input",
            placeholder="ELIMINAR",
        )
        if st.button("Confirmar eliminación", key="_delete_account_btn", use_container_width=True):
            if _del_confirm.strip().upper() == "ELIMINAR":
                _del_user = st.session_state.get("_username", "")
                with st.spinner("Eliminando cuenta…"):
                    _ok = _soft_delete_account(_del_user)
                if _ok:
                    for k in ["_authenticated","_user_name","_user_role","_username"]:
                        st.session_state.pop(k, None)
                    st.session_state["_deleted_account_msg"] = True
                    st.rerun()
                else:
                    st.error("No se pudo completar la eliminación. Contacta a soporte.")
            else:
                st.warning("Debes escribir exactamente ELIMINAR para confirmar.")

    # Botón Introducción — siempre visible debajo de Cerrar sesión
    if st.button("Introducción", key="_btn_intro", use_container_width=True):
        st.session_state["_show_welcome"] = True
        st.rerun()

    st.markdown('<hr style="border:none;border-top:1px solid #CBD5E1;margin:6px 0 10px;">', unsafe_allow_html=True)
    st.markdown(
        '<div style="font-size:10px;color:#6B7280;letter-spacing:3px;text-transform:uppercase;'
        'font-weight:700;padding:0 4px 6px;">Módulo de análisis</div>',
        unsafe_allow_html=True)
    _show_welcome_now = st.session_state.get("_show_welcome", False)

    def _on_module_select():
        st.session_state["_show_welcome"] = False
        # Si se selecciona desde modo intro, sincronizar al key principal
        _v = st.session_state.get("_tipo_op_intro_inactive")
        if _v:
            st.session_state["tipo_operacion"] = _v

    _modules = ["Proyecto Inmobiliario", "Proyecto Logístico / Industrial", "Proyecto de Oficinas", "Inmueble Residencial", "Retail / Local Comercial", "Portfolio"]
    _current_mod = st.session_state.get("tipo_operacion", "Proyecto Inmobiliario") or "Proyecto Inmobiliario"

    if _show_welcome_now:
        # Key distinto → Streamlit lo trata como widget nuevo → index=None funciona de verdad
        st.radio(
            "tipo_op_radio",
            _modules,
            index=None,
            key="_tipo_op_intro_inactive",
            label_visibility="collapsed",
            on_change=_on_module_select,
        )
        tipo_op = _current_mod
    else:
        _radio_index = _modules.index(_current_mod) if _current_mod in _modules else 0
        tipo_op = st.radio(
            "tipo_op_radio",
            _modules,
            index=_radio_index,
            key="tipo_operacion",
            label_visibility="collapsed",
            on_change=_on_module_select,
        ) or _current_mod

    # ── Descripción contextual — siempre visible (usa módulo activo o Proyecto Inmobiliario como preview)
    _mod_ctx = {
        "Proyecto Inmobiliario": (
            "🏗", "Desarrollo residencial multifamiliar",
            "Cabida normativa · Financiero · RIN · PDF",
            "Úsalo cuando tienes un terreno y quieres proyectar pisos, unidades, costos y rentabilidad de un edificio de departamentos.",
        ),
        "Proyecto Logístico / Industrial": (
            "🏭", "Nave logística · Almacén · Industria",
            "Costo · Yield · DSCR · Comparativa",
            "Úsalo para evaluar la construcción o adquisición de una nave industrial, almacén logístico o planta de manufactura.",
        ),
        "Inmueble Residencial": (
            "🏠", "Valuación de inmueble existente",
            "Precio · Renta · Yield · Comparables",
            "Úsalo cuando tienes un departamento, casa o unidad residencial ya construida y quieres analizar su valor o rentabilidad.",
        ),
        "Proyecto de Oficinas": (
            "🏢", "Alquiler · Compra · Desarrollo de Proyecto",
            "Yield · TIR · Financiero · Comparativa",
            "Úsalo para analizar el alquiler o compra de una oficina existente, o para proyectar el desarrollo de un edificio de oficinas.",
        ),
        "Retail / Local Comercial": (
            "🏪", "Local · Strip Mall · Mixed-Use · Dark Kitchen",
            "NOI · Cap Rate · OCR · Yield",
            "Evalúa la inversión, arrendamiento o desarrollo de activos retail en Lima — locales en avenida, strip malls, dark kitchens y comercio en planta baja de proyectos mixtos.",
        ),
        "Portfolio": (
            "📁", "Proyectos guardados",
            "KPIs · Historial · Comparativa",
            "Vista consolidada de todos los proyectos analizados y guardados. Compara KPIs entre proyectos y revisa el historial de versiones.",
        ),
    }
    # En pantalla introductoria: mostrar las 5 cards para familiarizarse con los módulos
    if _show_welcome_now:
        for _mk, (_mmi, _mmt, _mmtag, _mmd) in _mod_ctx.items():
            st.markdown(
                f'<div style="background:#F1F5F9;border-radius:9px;padding:10px 12px;'
                f'border:1px solid #CBD5E1;margin:0 0 6px;">'
                f'<div style="font-size:11px;font-weight:700;color:#0D2137;margin-bottom:2px;">'
                f'{_mmi} {_mmt}</div>'
                f'<div style="font-size:10px;color:rgba(71,85,105,0.80);letter-spacing:1px;'
                f'text-transform:uppercase;font-weight:600;margin-bottom:4px;">{_mmtag}</div>'
                f'<div style="font-size:10px;color:#475569;line-height:1.45;">{_mmd}</div>'
                f'</div>',
                unsafe_allow_html=True)
    else:
        _ctx_key = (tipo_op if tipo_op in _mod_ctx else "Proyecto Inmobiliario")
        _mi, _mt, _mtag, _md = _mod_ctx[_ctx_key]
        st.markdown(
            f'<div style="background:#F1F5F9;border-radius:9px;padding:11px 13px;'
            f'border:1px solid #CBD5E1;margin:6px 0 4px;">'
            f'<div style="font-size:12px;font-weight:700;color:#0D2137;margin-bottom:2px;">'
            f'{_mi} {_mt}</div>'
            f'<div style="font-size:11px;color:rgba(71,85,105,0.80);letter-spacing:1px;'
            f'text-transform:uppercase;font-weight:600;margin-bottom:6px;">{_mtag}</div>'
            f'<div style="font-size:11px;color:#475569;line-height:1.5;">{_md}</div>'
            f'</div>',
            unsafe_allow_html=True)
    st.markdown("---")

    # ── Helper compartido: render de paso de progreso ────
    def _sp(idx, lbl, sub, done, is_cur, is_last):
        if done:
            circle_style = "background:#22C55E;"
            cco, ctxt = "#FFFFFF", "✓"
            lco, sco, lnc = "#166534", "#4ADE80", "rgba(34,197,94,0.30)"
        elif is_cur:
            circle_style = "background:rgba(13,33,55,0.10);border:1.5px solid #0D2137;"
            cco, ctxt = "#0D2137", str(idx+1)
            lco, sco, lnc = "#0D2137", "#6B7280", "#CBD5E1"
        else:
            circle_style = "background:rgba(0,0,0,0.03);border:1px solid #E2E8F0;"
            cco, ctxt = "#CBD5E1", str(idx+1)
            lco, sco, lnc = "#94A3B8", "#CBD5E1", "#E2E8F0"
        ln = "" if is_last else f'<div style="width:1px;height:13px;background:{lnc};margin:2px auto;"></div>'
        return (f'<div style="display:flex;align-items:flex-start;gap:10px;margin-bottom:2px;">'
                f'<div style="display:flex;flex-direction:column;align-items:center;flex-shrink:0;">'
                f'<div style="width:22px;height:22px;border-radius:50%;{circle_style}'
                f'display:flex;align-items:center;justify-content:center;'
                f'font-size:10px;font-weight:700;color:{cco};">{ctxt}</div>{ln}</div>'
                f'<div style="padding-top:3px;">'
                f'<div style="font-size:11px;font-weight:600;color:{lco};line-height:1.2;">{lbl}</div>'
                f'<div style="font-size:10px;color:{sco};line-height:1.3;">{sub}</div>'
                f'</div></div>')

    # ── Inputs de módulo: solo cuando NO está en pantalla de bienvenida ─────
    # ── MÓDULO 1: PROYECTO INMOBILIARIO ──────────────────
    if tipo_op == "Proyecto Inmobiliario" and not _show_welcome_now:
        # ── Indicador de progreso guiado ─────────────────
        # Pasos independientes — cada uno refleja su propia condición sin cadena rígida
        _step1_done = (bool(st.session_state.get("nombre_proyecto", "").strip())
                       or bool(st.session_state.get("cert_bytes"))
                       or bool(st.session_state.get("cert")))
        _step2_done = (bool(st.session_state.get("cert_bytes"))
                       or bool(st.session_state.get("cert"))
                       or bool(st.session_state.get("partida_bytes"))
                       or bool(st.session_state.get("partida")))
        _step3_done = (int(st.session_state.get("cab_precio_compra_inp", 0) or 0) > 0
                       and int(st.session_state.get("cab_pventa_inp", 0) or 0) > 0)  # key corregido
        _step4_done = (st.session_state.get("cabida") is not None
                       and st.session_state.get("financ") is not None)
        _steps_prog = [
            ("Ingreso de Información del Inmueble", "Nombre, ubicación, área",          _step1_done),
            ("Documentos del Inmueble",             "Certificado, partida, planos",      _step2_done),
            ("Costos Financieros",                  "Precio compra y venta/m²",          _step3_done),
            ("Resumen Ejecutivo",                   "Cabida, finanzas, informe",         _step4_done),
        ]
        _current_step = next((i for i, (_, _, d) in enumerate(_steps_prog) if not d), 4)
        _prog_html = "".join([_sp(i,l,s,d,i==_current_step,i==3) for i,(l,s,d) in enumerate(_steps_prog)])
        st.markdown(
            f'<div style="background:#F1F5F9;border-radius:10px;padding:12px 14px 10px;'
            f'border:1px solid #CBD5E1;margin-bottom:10px;">'
            f'<div style="font-size:11px;font-weight:700;color:#94A3B8;'
            f'letter-spacing:2px;text-transform:uppercase;margin-bottom:10px;">FLUJO DE ANÁLISIS IA</div>'
            f'{_prog_html}</div>',
            unsafe_allow_html=True)
        st.markdown("---")
        st.markdown("### INGRESO DE INFORMACIÓN DEL INMUEBLE")
        nombre_proyecto = st.text_input(
            "Nombre del proyecto",
            placeholder="Ej: Torres Las Camelias — Miraflores",
            key="nombre_proyecto")
        _cab_zona_keys = list(MERCADO.keys())
        _cab_zona_saved = st.session_state.get("cab_zona_sel", "Miraflores")
        _cab_zona_default = _cab_zona_keys.index(_cab_zona_saved) if _cab_zona_saved in _cab_zona_keys else min(20, len(_cab_zona_keys) - 1)
        zona = st.selectbox("Ubicación", _cab_zona_keys, index=_cab_zona_default, key="cab_zona_sel_widget")

        with st.expander("📄 Documentos del Inmueble", expanded=False):
            _doc_types = ["pdf", "jpg", "jpeg", "png", "webp"]
            _plan_types = ["pdf", "dwg", "dxf", "jpg", "jpeg", "png", "webp"]
            pdf_cert    = st.file_uploader("Certificado de Parámetros ✱",       type=_doc_types, key="cert")
            pdf_plano   = st.file_uploader("Planos (perimetral / topográfico)",  type=_plan_types, key="plano",
                                           accept_multiple_files=True)
            pdf_partida = st.file_uploader("Partida Registral",                  type=_doc_types, key="partida")
            pdf_puhr    = st.file_uploader("PU / HR",                            type=_doc_types, key="puhr")
            pdf_norms   = st.file_uploader("Ordenanzas y normativa",             type=_doc_types, key="norms",
                                           accept_multiple_files=True)

        # Cachear bytes en session_state apenas se suben (con huella para no re-leer)
        if pdf_cert is not None:
            _cs = f"{pdf_cert.name}:{pdf_cert.size}"
            if st.session_state.get("_fp_cert") != _cs:
                st.session_state.cert_bytes = pdf_cert.read()
                st.session_state["_fp_cert"] = _cs
        if pdf_partida is not None:
            _ps = f"{pdf_partida.name}:{pdf_partida.size}"
            if st.session_state.get("_fp_partida") != _ps:
                st.session_state.partida_bytes = pdf_partida.read()
                st.session_state["_fp_partida"] = _ps
                st.session_state.legal = None  # nuevo doc → borrar resultado anterior
        if pdf_puhr is not None:
            _us = f"{pdf_puhr.name}:{pdf_puhr.size}"
            if st.session_state.get("_fp_puhr") != _us:
                st.session_state.puhr_bytes = pdf_puhr.read()
                st.session_state["_fp_puhr"] = _us
                st.session_state.legal = None

        st.markdown("---")
        st.markdown("### DESCRIPCIÓN DEL INMUEBLE")
        with st.expander("Medidas del lote", expanded=False):
            st.caption("Completa o adiciona información del inmueble para enriquecer el análisis.")
            col_fr, col_fo = st.columns(2)
            override_frente = col_fr.number_input("Frente (ml)", min_value=0.0, max_value=500.0,
                                                  value=float(st.session_state.get("cab_override_frente", 0.0)), step=0.5,
                                                  key="cab_frente_inp")
            override_fondo  = col_fo.number_input("Fondo (ml)",  min_value=0.0, max_value=500.0,
                                                  value=float(st.session_state.get("cab_override_fondo", 0.0)), step=0.5,
                                                  key="cab_fondo_inp")

            _area_calc = round(override_frente * override_fondo, 1) if override_frente > 0 and override_fondo > 0 else 0.0

            # Auto-poblar área cuando frente o fondo cambian
            if _area_calc > 0 and (
                override_frente != st.session_state.get("_cab_prev_frente", 0.0) or
                override_fondo  != st.session_state.get("_cab_prev_fondo",  0.0)
            ):
                st.session_state["cab_area_inp"] = _area_calc
            st.session_state["_cab_prev_frente"] = override_frente
            st.session_state["_cab_prev_fondo"]  = override_fondo

            if _area_calc > 0:
                st.markdown(f'<div style="font-size:12px;color:#475569;font-weight:600;">Área calculada: {_area_calc:,.1f} m² <span style="font-weight:400;color:#8A9AB0;">(frente × fondo)</span></div>', unsafe_allow_html=True)

            override_area = st.number_input("Área del terreno (m²)", min_value=0.0, max_value=50000.0,
                                            value=float(st.session_state.get("cab_override_area", _area_calc)), step=10.0, key="cab_area_inp")
            override_al   = st.number_input("Área libre mínima (%)", min_value=0.0, max_value=80.0,
                                            value=0.0, step=5.0,
                                            key="cab_override_al_inp")

        with st.expander("Colindantes", expanded=False):
            st.caption("Norma por Colindancia — Se activa cuando las edificaciones colindantes superan la altura permitida, otorgando beneficio de altura al proyecto.")
            _col_izq, _col_der = st.columns(2)
            colind_izq = _col_izq.number_input("Colindante izq. (pisos)", min_value=0, max_value=40,
                                                value=0, step=1,
                                                key="cab_colind_izq_inp")
            colind_der = _col_der.number_input("Colindante der. (pisos)", min_value=0, max_value=40,
                                                value=0, step=1,
                                                key="cab_colind_der_inp")
            if colind_izq > 0 or colind_der > 0:
                _col_max = max(colind_izq, colind_der)
                st.caption(f"Regla colindancia: edificio a analizar podrá alcanzar hasta el promedio "
                           f"con el colindante más alto ({_col_max} pisos). Claude calculará la altura permitida.")

        st.markdown("---")
        with st.expander("📋 Costos Proyectados", expanded=True):
            _financ_inputs_ss = st.session_state.get("financ_inputs") or {}

            # Inicializar keys de widgets solo si no existen (evita conflicto value/key en Streamlit)
            if "cab_precio_compra_inp" not in st.session_state:
                _pcompra_init = int(
                    ((_financ_inputs_ss.get("costo_terreno") or 0) if isinstance(_financ_inputs_ss, dict) else 0)
                    or 1
                )
                st.session_state["cab_precio_compra_inp"] = max(1, _pcompra_init)
            if "cab_pventa_inp" not in st.session_state:
                st.session_state["cab_pventa_inp"] = 0
            if "cab_cconst_inp" not in st.session_state:
                st.session_state["cab_cconst_inp"] = 700

            precio_compra   = st.number_input("Precio de compra del inmueble (USD)",
                                              min_value=1, max_value=50_000_000,
                                              step=10_000, format="%d", key="cab_precio_compra_inp")
            if precio_compra > 0:
                st.markdown(f'<div style="font-size:11px;color:#475569;font-weight:600;margin-top:-6px;">= ${precio_compra:,.0f} USD</div>', unsafe_allow_html=True)

            precio_venta_m2 = st.number_input("Precio de venta / m² (USD)",
                                          min_value=0, max_value=15_000,
                                          step=100, key="cab_pventa_inp")
        _ref_p1 = MERCADO.get(zona, {}).get("precio_1br", 0)
        _ref_p2 = MERCADO.get(zona, {}).get("precio_2br", 0)
        _ref_p3 = MERCADO.get(zona, {}).get("precio_3br", 0)
        _m_zona = MERCADO.get(zona, {})
        # ── Referencia de mercado y sugerencia de precio ──────────
        if _ref_p2 > 0:
            if precio_venta_m2 == 0:
                pass
            else:
                _diff_ref = (precio_venta_m2 - _ref_p2) / _ref_p2 * 100 if _ref_p2 > 0 else 0
                # Clasificación por tier de posicionamiento — sin alarmar por precio premium
                if _diff_ref < -10:
                    _tier_lbl  = "Por debajo de la mediana del distrito"
                    _tier_bg   = "#F0F0F0"; _tier_tc = "#5A5A5A"; _tier_bc = "#AAAAAA"
                    _tier_note = "Verificar si el precio es competitivo para el nivel de acabados proyectado"
                elif _diff_ref < 0:
                    _tier_lbl  = f"Cerca de la mediana del distrito ({_diff_ref:+.0f}%)"
                    _tier_bg   = "#F0FBF5"; _tier_tc = "#1A4731"; _tier_bc = "#6BAE90"
                    _tier_note = None
                elif _diff_ref <= 15:
                    _tier_lbl  = f"Alineado con el mercado ({_diff_ref:+.0f}% sobre mediana)"
                    _tier_bg   = "#F0FBF5"; _tier_tc = "#1A4731"; _tier_bc = "#6BAE90"
                    _tier_note = "Consistente con proyecto de acabados estándar a medio en la zona"
                elif _diff_ref <= 35:
                    _tier_lbl  = f"Posicionamiento premium ({_diff_ref:+.0f}% sobre mediana)"
                    _tier_bg   = "#FFFAF0"; _tier_tc = "#7A5000"; _tier_bc = "#D4A843"
                    _tier_note = "Normal para proyectos con acabados importados, amenidades exclusivas o ubicación diferenciada"
                elif _diff_ref <= 60:
                    _tier_lbl  = f"Segmento luxury ({_diff_ref:+.0f}% sobre mediana)"
                    _tier_bg   = "#F8F4ED"; _tier_tc = "#5A3A10"; _tier_bc = "#475569"
                    _tier_note = "Verificar absorción esperada y comparables de proyectos luxury activos en la zona"
                else:
                    _tier_lbl  = f"Prima muy alta ({_diff_ref:+.0f}% sobre mediana)"
                    _tier_bg   = "#FFF0F0"; _tier_tc = "#7A1A1A"; _tier_bc = "#E07A5F"
                    _tier_note = "Contrastar con proyectos comparables — prima de esta magnitud puede afectar la velocidad de absorción"

                pass  # Card de posicionamiento eliminado — dato contextual no accionable
        _def_estac = int((_financ_inputs_ss.get("precio_estac") or 0) or _m_zona.get("precio_estac", 0))
        _def_dep   = int((_financ_inputs_ss.get("precio_deposito") or 0) or _m_zona.get("precio_deposito", 0))
        _col_pe, _col_pd = st.columns(2)
        with _col_pe:
            precio_estac_inp = st.number_input(
                "Precio cochera (USD)", min_value=0, max_value=100_000,
                value=_def_estac, step=500, key="cab_precio_estac_inp")
        with _col_pd:
            precio_deposito_inp = st.number_input(
                "Precio depósito (USD)", min_value=0, max_value=50_000,
                value=_def_dep, step=250, key="cab_precio_deposito_inp")
        costo_const_m2  = st.number_input("Costo construcción dptos / m² (USD)",
                                          min_value=300, max_value=3_000,
                                          step=25, key="cab_cconst_inp")
        with st.expander("Costos avanzados"):
            costo_sotano_m2 = st.number_input("Costo sótano / m² (USD)", 200, 1000, 450, 25,
                                                key="cab_costo_sotano_inp")
            _fi_arq = float((_financ_inputs_ss.get("costo_arq_m2") or 5.94))
            _fi_esp = float((_financ_inputs_ss.get("costo_esp_m2") or 7.92))
            _fi_fac = int((_financ_inputs_ss.get("costo_factibilidades") or 17000))
            _col_arq, _col_esp = st.columns(2)
            with _col_arq:
                costo_arq_m2 = st.number_input(
                    "Planos arquitectura / m² (USD)", 1.0, 50.0, _fi_arq, 0.5,
                    key="cab_costo_arq_inp")
            with _col_esp:
                costo_esp_m2 = st.number_input(
                    "Especialidades / m² (USD)", 1.0, 50.0, _fi_esp, 0.5,
                    key="cab_costo_esp_inp")
            costo_factibilidades = st.number_input(
                "Factibilidades (USD)", 0, 100_000, _fi_fac, 1000,
                key="cab_costo_factib_inp")
            _estructura_opts = ["Terreno como aporte (estándar)", "Banco financia terreno (con track record)"]
            _estructura_sel  = st.radio(
                "Estructura de financiamiento",
                _estructura_opts, index=0,
                key="cab_estructura_financ_inp")
            estructura_financ = "estandar" if _estructura_sel == _estructura_opts[0] else "con_terreno"
            if estructura_financ == "con_terreno":
                aporte_propio_pct = st.number_input(
                    "Aporte inicial terreno (%)", 10.0, 40.0, 20.0, 5.0,
                    key="cab_aporte_propio_inp")
            else:
                aporte_propio_pct = 100.0
                st.caption("Terreno 100% equity → sirve de garantía hipotecaria para la línea de construcción")
            st.markdown("---")
            # Preventa
            import math as _m_sb
            _n_unid_sb   = int((st.session_state.get("cabida") or {}).get("total_unidades", 20) or 20)
            _vel_sb      = float(MERCADO.get(st.session_state.get("zona", ""), {}).get("velocidad_venta", 1.5) or 1.5)
            _fi_sb       = st.session_state.get("financ_inputs") or {}
            pct_preventa_banco = st.number_input(
                "Preventa mínima exigida por banco (%)", 10.0, 50.0,
                float(_fi_sb.get("pct_preventa_banco", 30.0)), 5.0,
                key="cab_pct_preventa_banco_inp")
