                _res_po1.number_input("Opción de compra (%)", 0.0, 20.0, 5.0, 0.5, key="res_prop_opcion_pct")
                _res_po2.number_input("Minuta / contrato (%)", 0.0, 50.0, 20.0, 5.0, key="res_prop_minuta_pct")
                _res_pv1, _res_pv2 = st.columns(2)
