                _av_m2 = c.get("area_vendible_m2", 0) or 0
                _pct_vend = round(_av_m2 / _at_m2 * 100, 1) if _at_m2 > 0 else 0
                _lote_m2  = float((p or {}).get("area_terreno_m2", 0) or 0)
