                    ("TIR anual",          lambda e: f"{e[4]['tir_anual_pct']:.1f}%",                 "tir_anual_pct", (15, 10)),
                    ("ROI",                lambda e: f"{e[4]['roi_pct']:.1f}%",                       "roi_pct",       (20, 12)),
                    ("Break-even m²",      lambda e: f"${e[4]['be_precio_m2']:,}",                    None,  None),
